module.exports=[99193,a=>{"use strict";let b=[{slug:"boots-opticians",name:"Boots Opticians",shortName:"Boots",brandColor:"#0064d2",description:"Boots Opticians is one of the UK's largest and most recognised optical chains, operating from Boots pharmacy stores across the country. They offer a full range of eye care services including NHS and private eye tests, designer and own-brand glasses, contact lenses, and hearing care. With their convenient high-street locations and integration with Boots Advantage Card loyalty points, they remain a popular choice for routine eye care.",services:["NHS Eye Tests","Private Eye Tests","Contact Lenses","Glasses","Hearing Tests","Children's Eye Tests","OCT Scan","Diabetic Screening"],storeCount:600,website:"https://www.boots-opticians.co.uk",priceRange:"Free NHS / From £25 private",nhsAvailable:!0,available:!0,highlights:["Earn and spend Boots Advantage Card points on eye care","Wide selection of designer frames from brands like Ray-Ban, Oakley, and Prada","Enhanced eye tests with OCT scanning available at most locations","Convenient locations inside Boots pharmacy stores nationwide"],founded:"1983",storeLocations:["london","croydon","bromley","kingston-upon-thames","richmond","ealing","brighton","reading","oxford","guildford","canterbury","southampton","portsmouth","maidstone","milton-keynes","slough","crawley","tunbridge-wells","basingstoke","chichester","worthing","bristol","bath","exeter","plymouth","bournemouth","swindon","gloucester","cheltenham","taunton","torquay","truro","cambridge","norwich","ipswich","colchester","chelmsford","luton","peterborough","southend-on-sea","bedford","st-albans","birmingham","coventry","wolverhampton","stoke-on-trent","worcester","hereford","nottingham","leicester","derby","northampton","lincoln","manchester","liverpool","chester","warrington","preston","blackpool","bolton","lancaster","carlisle","newcastle","sunderland","durham","middlesbrough","darlington","leeds","sheffield","york","bradford","hull","huddersfield","doncaster","harrogate","cardiff","swansea","newport","wrexham","aberystwyth","bangor","edinburgh","glasgow","aberdeen","dundee","inverness","stirling","perth","belfast","derry","newry"],history:"Boots Opticians traces its origins to 1983, when Boots the Chemist — already one of Britain's most trusted pharmacy brands — launched a dedicated optical division within its existing high-street stores. The move was a natural extension of the company's healthcare heritage, which stretches back to John Boot's original herbalist shop in Nottingham in 1849. By placing opticians inside busy pharmacy locations, Boots offered a level of convenience that few competitors could match, and the optical business grew rapidly through the 1980s and 1990s.\n\nIn 2009, Boots Opticians was acquired by the Italian eyewear conglomerate Luxottica, which later merged with Essilor in 2018 to form EssilorLuxottica — the world's largest eyewear and lens company. This ownership change gave Boots Opticians access to an enormous portfolio of premium frame brands, including Ray-Ban, Oakley, Persol, and many others manufactured or licensed by the parent group. Despite the corporate changes at the top, the day-to-day experience for customers remained largely consistent, with the brand retaining its familiar high-street presence.\n\nToday, Boots Opticians operates approximately 600 stores across the United Kingdom, making it the second-largest optical chain in the country. The business continues to invest in clinical technology, rolling out OCT scanning and digital retinal photography across its network. Its integration with the Boots Advantage Card loyalty programme remains a significant draw for customers, allowing them to earn and spend points across both pharmacy and optical services. Boots Opticians also participates fully in the NHS sight test voucher scheme, providing free eye tests to eligible patients.",detailedServices:[{name:"NHS Eye Test",description:"A comprehensive eye examination carried out by a qualified optometrist, available free to eligible patients including children under 16, over-60s, those receiving certain benefits, and patients with specific medical conditions. The test checks visual acuity, eye health, and screens for conditions such as glaucoma and cataracts.",price:"Free (if eligible)",duration:"20-25 minutes",nhsCovered:!0},{name:"Private Eye Test",description:"A full eye examination for patients who do not qualify for a free NHS test. Includes the same clinical checks as the NHS test — visual acuity assessment, refraction, eye pressure measurement, and an examination of the internal and external structures of the eye using a slit lamp and ophthalmoscope.",price:"From £25",duration:"20-25 minutes",nhsCovered:!1},{name:"Enhanced Eye Test with OCT Scan",description:"An advanced eye examination that includes Optical Coherence Tomography (OCT), a non-invasive imaging test that produces detailed cross-section images of the retina. OCT scanning can detect early signs of conditions such as macular degeneration, diabetic retinopathy, and glaucoma — often before symptoms appear. This is Boots' most thorough eye health check.",price:"From £45",duration:"30-35 minutes",nhsCovered:!1},{name:"Contact Lens Consultation",description:"An initial assessment to determine your suitability for contact lenses. The consultation includes measurements of your corneal curvature, tear film assessment, and a trial fitting. Your optician will discuss different lens types — daily disposables, monthly lenses, and toric lenses for astigmatism — and recommend the best option for your prescription and lifestyle.",price:"From £35",duration:"30-40 minutes",nhsCovered:!1},{name:"Children's Eye Test",description:"A specially adapted eye test for children, using age-appropriate charts and techniques. All children under 16 are entitled to a free NHS-funded eye test. The optometrist will check for common childhood vision problems including lazy eye (amblyopia), squint (strabismus), and long or short-sightedness. Boots stocks a wide range of children's frames, many available free under the NHS voucher scheme.",price:"Free (NHS funded)",duration:"20-30 minutes",nhsCovered:!0},{name:"Hearing Test",description:"A hearing assessment carried out by a qualified audiologist at selected Boots Opticians locations. The test includes a lifestyle questionnaire, an ear examination using an otoscope, and a pure tone audiometry test to measure hearing sensitivity across different frequencies. Results are explained clearly and, if needed, hearing aid options are discussed.",price:"Free",duration:"30 minutes",nhsCovered:!1},{name:"Diabetic Eye Screening",description:"A specialist screening service for patients with diabetes, checking for diabetic retinopathy — a complication that can damage blood vessels in the retina. The screening includes digital retinal photography and, in many locations, OCT scanning. Early detection through regular screening is essential for preventing vision loss in diabetic patients.",price:"From £30",duration:"20-25 minutes",nhsCovered:!1}],bookingProcess:["Search for your nearest Boots Opticians store by entering your postcode on eyetest.co.uk","Compare available appointment slots, prices, and services at nearby stores","Select your preferred date, time, and test type — NHS eye test, private eye test, or enhanced OCT scan","Enter your personal details and any relevant medical information","Receive instant confirmation by email and SMS with your appointment details","Attend your appointment — remember to bring your current glasses or contact lenses and any NHS exemption evidence"],prosAndCons:{pros:["Earn Boots Advantage Card points on every purchase, including eye tests and glasses","Huge range of designer and premium frames thanks to EssilorLuxottica ownership","Convenient locations inside Boots pharmacy stores with long opening hours","Advanced clinical technology including OCT scanning available at most stores","NHS eye tests available alongside private and enhanced options"],cons:["Appointment slots can be limited at busy high-street locations, especially at weekends","Some patients report feeling upsold towards more expensive lens coatings and add-ons","Budget frame selection is smaller compared to value-focused competitors like ASDA"]},faqs:[{q:"Can I use my Boots Advantage Card when buying glasses?",a:"Yes, you can earn and spend Boots Advantage Card points across all Boots Opticians purchases, including eye tests, glasses, sunglasses, and contact lenses. You earn 4 points per pound spent in store. Points earned at Boots Opticians can be spent anywhere in the Boots group, and vice versa, making it a genuinely useful loyalty benefit for regular customers."},{q:"How much does an eye test cost at Boots Opticians?",a:"If you are eligible for an NHS-funded eye test — including children under 16, adults over 60, people receiving certain benefits, and those with specific medical conditions — the test is completely free. For patients who are not eligible for the NHS test, private eye tests start from around £25. The enhanced eye test with OCT scan, which provides a more detailed examination of the retina, starts from £45."},{q:"What is the OCT scan at Boots and is it worth it?",a:"OCT (Optical Coherence Tomography) is a non-invasive imaging technology that produces detailed 3D cross-section images of your retina. It can detect early signs of eye conditions such as glaucoma, macular degeneration, and diabetic retinopathy — often years before symptoms become noticeable. Many optometrists recommend it as a valuable baseline for patients over 25, particularly those with a family history of eye disease. While it is an additional cost on top of the standard test, it provides a much more thorough picture of your eye health."},{q:"Does Boots Opticians offer home eye tests?",a:"Boots Opticians does not widely offer a home visit eye testing service. Their eye tests are carried out in-store at Boots pharmacy locations. If you or a family member is unable to leave home due to illness or disability, you may want to consider opticians such as Specsavers or Scrivens, who provide dedicated home visit services for housebound patients."},{q:"How long does an eye test take at Boots?",a:"A standard NHS or private eye test at Boots Opticians typically takes around 20 to 25 minutes. If you opt for the enhanced eye test with OCT scan, you should allow approximately 30 to 35 minutes. Contact lens consultations tend to take a little longer — around 30 to 40 minutes — as they include additional measurements and a trial fitting."},{q:"Can I get my glasses the same day at Boots Opticians?",a:"Boots Opticians does not typically offer same-day glasses. Most orders are sent to a central glazing laboratory, and you can expect your glasses to be ready for collection within 7 to 10 working days. Some stores may offer an express service for simple prescriptions, but availability varies by location. You will be notified by text or email when your glasses are ready to collect."},{q:"What frame brands does Boots Opticians stock?",a:"Boots Opticians carries an extensive range of designer and own-brand frames. Thanks to being part of the EssilorLuxottica group, they have access to brands including Ray-Ban, Oakley, Prada, Versace, Dolce & Gabbana, Burberry, Ralph Lauren, and many more. They also offer their own Boots-branded frames at more affordable price points, and children's ranges featuring popular character brands."},{q:"Does Boots Opticians accept NHS vouchers for glasses?",a:"Yes, Boots Opticians fully participates in the NHS optical voucher scheme. If you are eligible for an NHS voucher, it can be put towards the cost of your glasses or contact lenses. The voucher value depends on your prescription strength, and any difference between the voucher value and the cost of your chosen frames and lenses is paid by you. Children and some adults on qualifying benefits can receive glasses entirely covered by the NHS voucher."}]},{slug:"specsavers",name:"Specsavers Optical Group",shortName:"Specsavers",brandColor:"#1b5e20",description:"Specsavers is the UK's largest optical retailer, founded in Guernsey by Doug and Dame Mary Perkins. Known for their value-for-money approach and iconic advertising campaigns, they operate a joint-venture partnership model where each store is co-owned by local optometrists. They provide comprehensive eye care, hearing services, and home visit testing across the UK and internationally.",services:["NHS Eye Tests","Private Eye Tests","Contact Lenses","Glasses","Hearing Tests","Home Visits","Children's Eye Tests","OCT Scan","Diabetic Screening"],storeCount:900,website:"https://www.specsavers.co.uk",priceRange:"Free NHS / From £25 private",nhsAvailable:!0,available:!1,highlights:["UK's largest optical chain with over 900 stores","Two-for-one offers on a wide range of glasses","Home visit service available for those unable to attend a store","Joint-venture model means each store is part-owned by its optometrists"],founded:"1984",storeLocations:["london","croydon","bromley","kingston-upon-thames","richmond","ealing","brighton","reading","oxford","guildford","canterbury","southampton","portsmouth","maidstone","milton-keynes","slough","crawley","tunbridge-wells","basingstoke","chichester","worthing","bristol","bath","exeter","plymouth","bournemouth","swindon","gloucester","cheltenham","taunton","torquay","truro","cambridge","norwich","ipswich","colchester","chelmsford","luton","peterborough","southend-on-sea","bedford","st-albans","birmingham","coventry","wolverhampton","stoke-on-trent","worcester","hereford","nottingham","leicester","derby","northampton","lincoln","manchester","liverpool","chester","warrington","preston","blackpool","bolton","lancaster","carlisle","newcastle","sunderland","durham","middlesbrough","darlington","leeds","sheffield","york","bradford","hull","huddersfield","doncaster","harrogate","cardiff","swansea","newport","wrexham","aberystwyth","bangor","edinburgh","glasgow","aberdeen","dundee","inverness","stirling","perth","belfast","derry","newry"],history:"Specsavers was founded in 1984 by Doug and Dame Mary Perkins, both qualified optometrists, on the island of Guernsey. The couple had previously run a small chain of optical practices in the West Country but sold up and moved to the Channel Islands with a vision to create an entirely new kind of opticians — one that would bring professional eye care to the high street at genuinely affordable prices. The timing proved crucial: the UK government had recently deregulated the optical industry, allowing advertising of spectacle prices for the first time and opening the door to competitive pricing.\n\nThe first Specsavers stores opened in Guernsey and Bristol, and the business expanded rapidly through the late 1980s and 1990s. The founders introduced a joint-venture partnership model that proved central to the company's success: each store is co-owned by the resident optometrists, who share profits with the Specsavers group. This model aligns clinical and commercial interests, giving store directors a direct stake in patient satisfaction and store performance. By the early 2000s, Specsavers had become the UK's largest optical retailer, and the brand expanded into Australia, New Zealand, and northern Europe.\n\nToday, Specsavers operates over 2,700 stores globally, with more than 900 in the United Kingdom alone. The brand is known for its value-driven offers — particularly its iconic two-for-one deals — and its memorable advertising campaigns, including the long-running \"Should've gone to Specsavers\" slogan that has become a fixture of British popular culture. The company has diversified into hearing care, domiciliary eye care (home visits), and workplace eye care programmes. It remains privately owned by the Perkins family, with its headquarters still on Guernsey, and employs over 40,000 people worldwide.",detailedServices:[{name:"NHS Eye Test",description:"A thorough eye examination covered by the NHS for eligible patients. Specsavers optometrists assess visual acuity, refraction, eye coordination, and eye health using slit lamp examination and ophthalmoscopy. The test also includes a screening for glaucoma through intraocular pressure measurement. Eligible patients include children under 16, adults over 60, those receiving qualifying benefits, and people with certain medical conditions or a family history of glaucoma.",price:"Free (if eligible)",duration:"20-25 minutes",nhsCovered:!0},{name:"Private Eye Test",description:"A full eye examination for patients who do not qualify for a free NHS eye test. The examination includes all the same clinical checks as the NHS test, including visual acuity, refraction, eye pressure measurement, and a detailed assessment of the internal and external health of the eyes. Specsavers recommends eye tests every two years for most adults, or more frequently if advised by your optometrist.",price:"From £25",duration:"20-25 minutes",nhsCovered:!1},{name:"OCT Eye Health Check",description:"An enhanced screening that uses Optical Coherence Tomography (OCT) to produce 3D cross-section images of the retina and optic nerve. This advanced scan can detect signs of serious eye conditions — including glaucoma, macular degeneration, and diabetic eye disease — at a much earlier stage than a standard eye test alone. Specsavers recommends this for patients over 25 as a baseline measurement.",price:"From £25 (in addition to eye test)",duration:"10 minutes (plus eye test)",nhsCovered:!1},{name:"Contact Lens Assessment",description:"An initial appointment to assess your suitability for contact lenses. Includes corneal topography measurements, tear film evaluation, and a trial lens fitting. Your optometrist will discuss the available lens options — including daily disposables, extended wear, toric lenses for astigmatism, and multifocal lenses for presbyopia — and recommend the most suitable type for your eyes and lifestyle.",price:"From £30",duration:"30-40 minutes",nhsCovered:!1},{name:"Home Visit Eye Test",description:"A full NHS or private eye test carried out in the patient's own home by a Specsavers domiciliary optometrist. This service is available for people who cannot visit a store unaccompanied due to a physical or mental disability or illness. The optometrist brings portable equipment and a selection of frames, so glasses can be ordered during the same visit. NHS-funded home visits are free for eligible patients.",price:"Free (NHS eligible) / From £30 (private)",duration:"30-40 minutes",nhsCovered:!0},{name:"Hearing Test",description:"A comprehensive hearing assessment provided at Specsavers audiology clinics within their opticians stores. The test includes a discussion of your hearing history, an otoscopic examination of your ear canal, and a pure tone audiometry test carried out in a soundproof booth. If hearing loss is detected, the audiologist will explain your options, including NHS-funded and private digital hearing aids.",price:"Free",duration:"30 minutes",nhsCovered:!1},{name:"Children's Eye Test",description:"A specially adapted eye test for children from age 3 upwards, carried out by experienced paediatric-friendly optometrists. The test uses picture charts, matching games, and retinoscopy to assess vision in younger children who may not yet recognise letters. All children under 16 (and under 19 in full-time education) qualify for a free NHS eye test, and Specsavers offers a wide range of children's frames covered by the NHS voucher.",price:"Free (NHS funded)",duration:"20-30 minutes",nhsCovered:!0}],bookingProcess:["Enter your postcode on eyetest.co.uk to find Specsavers stores near you","Browse available appointment types — NHS eye test, private test, OCT scan, contact lens assessment, or hearing test","Select a convenient date and time slot from the available appointments","Provide your personal details and let us know if you have any accessibility requirements","Confirm your booking and receive a confirmation email with your appointment details and what to bring","Arrive at your appointment with your current glasses or lenses, any NHS exemption evidence, and a list of any medications you take"],prosAndCons:{pros:["The largest store network in the UK, making it easy to find a branch near you","Excellent value with regular two-for-one offers on a wide range of frames","Joint-venture model means your optometrist has a personal stake in your care","Comprehensive home visit service for housebound or elderly patients","Free hearing tests alongside optical services at most locations"],cons:["High-volume appointment scheduling means some patients feel rushed during their tests","Premium designer frame range is smaller than some competitors such as Boots or Vision Express","Not currently available for booking through eyetest.co.uk — check specsavers.co.uk directly"]},faqs:[{q:"How do I get a free eye test at Specsavers?",a:"You qualify for a free NHS-funded eye test if you are under 16 (or under 19 in full-time education), aged 60 or over, receiving certain means-tested benefits such as Income Support or Pension Credit, diagnosed with diabetes or glaucoma, or if you are over 40 and have a close family member with glaucoma. Simply let the receptionist know your eligibility when booking, and bring proof to your appointment."},{q:"What does the Specsavers two-for-one deal include?",a:"Specsavers' two-for-one offer lets you choose two pairs of glasses from selected ranges for the price of one pair, starting from £25. Many customers use this to get a pair of prescription glasses and a pair of prescription sunglasses, or to choose different frames for work and leisure. The offer applies to frame and lens combinations from the designated two-for-one range, and additional lens upgrades such as anti-reflection coatings may cost extra."},{q:"Can Specsavers come to my home for an eye test?",a:"Yes, Specsavers operates a domiciliary (home visit) eye test service for patients who are unable to leave home unaccompanied due to a physical or mental health condition or disability. A Specsavers optometrist will visit you at home with portable testing equipment and a selection of frames. If you qualify for an NHS eye test, the home visit is also free. To arrange a home visit, contact your local Specsavers store directly."},{q:"How often should I have an eye test at Specsavers?",a:"Specsavers recommends that most adults have an eye test every two years, or more frequently if advised by their optometrist. Children, people with diabetes, those over 70, and anyone with a family history of eye disease should typically have their eyes tested annually. Regular eye tests are important not just for updating your prescription but for detecting eye conditions early, when they are most treatable."},{q:"Does Specsavers offer laser eye surgery?",a:"No, Specsavers does not offer laser eye surgery or any surgical eye procedures. They are an optical retailer focused on eye testing, glasses, contact lenses, and hearing care. If you are interested in laser eye surgery, your Specsavers optometrist can advise you and refer you to an appropriate specialist or clinic."},{q:"Can I book a Specsavers appointment through eyetest.co.uk?",a:"Specsavers is not currently available for booking through eyetest.co.uk. We list Specsavers as a reference so customers can compare services and prices across different opticians. To book directly, visit specsavers.co.uk or call your local Specsavers store. We are working to bring Specsavers availability to our platform in the future."},{q:"What hearing aid brands does Specsavers offer?",a:"Specsavers works with major hearing aid manufacturers and also offers its own Advance range of digital hearing aids. NHS hearing aids are available free of charge for eligible patients through Specsavers audiology clinics. Private hearing aids start from around £495 per ear. All hearing aids come with an aftercare package including follow-up appointments and adjustments."},{q:"How long does it take to get glasses from Specsavers?",a:"Standard glasses orders from Specsavers typically take 7 to 10 working days to be ready for collection. More complex prescriptions, including varifocals and high-index lenses, may take a little longer. Specsavers will contact you by text message when your glasses are ready to pick up from the store. Some stores offer an express service for simple single-vision prescriptions, but availability varies."}]},{slug:"vision-express",name:"Vision Express",shortName:"Vision Express",brandColor:"#e65100",description:"Vision Express is a major UK optical chain owned by the EssilorLuxottica group, one of the world's largest eyewear companies. They offer a comprehensive range of eye tests, glasses, sunglasses, and contact lenses, with a strong emphasis on clinical excellence. Many of their stores are located in prominent high-street and retail park locations, and they carry an extensive portfolio of premium and designer frames.",services:["NHS Eye Tests","Private Eye Tests","Contact Lenses","Glasses","Children's Eye Tests","OCT Scan","Diabetic Screening"],storeCount:400,website:"https://www.visionexpress.com",priceRange:"Free NHS / From £30 private",nhsAvailable:!0,available:!1,highlights:["Part of the EssilorLuxottica group with access to exclusive frame brands","Advanced clinical technology including OCT and digital retinal photography","Price match guarantee on identical products","30-day satisfaction guarantee on all glasses purchases"],founded:"1988",storeLocations:["london","croydon","bromley","kingston-upon-thames","richmond","ealing","brighton","reading","oxford","guildford","canterbury","southampton","portsmouth","maidstone","milton-keynes","slough","crawley","tunbridge-wells","basingstoke","chichester","worthing","bristol","bath","exeter","plymouth","bournemouth","swindon","gloucester","cheltenham","taunton","torquay","cambridge","norwich","ipswich","colchester","chelmsford","luton","peterborough","southend-on-sea","st-albans","birmingham","coventry","wolverhampton","stoke-on-trent","worcester","nottingham","leicester","derby","northampton","lincoln","manchester","liverpool","chester","warrington","preston","blackpool","bolton","newcastle","sunderland","middlesbrough","leeds","sheffield","york","bradford","hull","huddersfield","doncaster","cardiff","swansea","newport","edinburgh","glasgow","aberdeen","dundee","belfast"],history:"Vision Express was founded in 1988 in Gateshead, Tyne and Wear, with a mission to provide high-quality eye care and fashionable eyewear on the British high street. The company expanded rapidly during the 1990s, opening stores in major town centres and retail parks across England, Scotland, Wales, and Northern Ireland. Its strategy of securing prominent retail locations — often with large, well-lit showrooms — helped it stand out from traditional opticians and attract a customer base interested in eyewear as much as a fashion accessory as a medical necessity.\n\nIn 2013, Vision Express was acquired by GrandVision, a Dutch optical retail group that operated thousands of stores worldwide. This acquisition provided Vision Express with greater purchasing power and access to a broader range of lens technology. The ownership changed again in 2021 when EssilorLuxottica — the global eyewear giant formed from the 2018 merger of French lens maker Essilor and Italian frame manufacturer Luxottica — completed its purchase of GrandVision. This made Vision Express a sister company to other well-known brands in the EssilorLuxottica portfolio, including Sunglass Hut and LensCrafters.\n\nToday, Vision Express operates around 400 stores across the UK and is known for its emphasis on clinical quality and advanced eye care technology. The chain has invested heavily in equipping its stores with OCT scanning and digital retinal photography, and it positions itself as a premium optician offering designer frames alongside comprehensive eye health assessments. Vision Express also offers a price match guarantee and a 30-day satisfaction guarantee on glasses, reflecting its confidence in both product quality and customer service.",detailedServices:[{name:"NHS Eye Test",description:"A full eye examination funded by the NHS for eligible patients. The test includes visual acuity assessment, refraction to determine your prescription, intraocular pressure measurement for glaucoma screening, and a detailed examination of the health of your eyes. Vision Express optometrists use advanced digital imaging equipment alongside traditional clinical techniques.",price:"Free (if eligible)",duration:"20-25 minutes",nhsCovered:!0},{name:"Private Eye Test",description:"A comprehensive eye examination for patients not eligible for NHS funding. The test covers all the same clinical assessments as the NHS test, with the addition of more time for discussion of visual needs and lifestyle factors that may influence your lens and frame choices. Vision Express private tests include a detailed report of your eye health.",price:"From £30",duration:"25-30 minutes",nhsCovered:!1},{name:"Advanced Eye Health Check with OCT",description:"Vision Express's most thorough eye examination, combining a standard eye test with OCT (Optical Coherence Tomography) scanning and digital retinal photography. The OCT scan creates a detailed 3D map of the layers of the retina and optic nerve, while retinal photography provides a high-resolution colour image of the back of the eye. Together, these technologies enable early detection of conditions including macular degeneration, glaucoma, and diabetic retinopathy.",price:"From £49",duration:"35-40 minutes",nhsCovered:!1},{name:"Contact Lens Fitting",description:"A specialist appointment to assess your suitability for contact lenses and find the best lens type for your needs. Includes corneal curvature measurements, tear film evaluation, and a trial lens fitting. Vision Express offers a wide range of contact lens options from leading manufacturers including Acuvue, Dailies, and Air Optix.",price:"From £40",duration:"30-45 minutes",nhsCovered:!1},{name:"Children's Eye Examination",description:"A friendly, age-appropriate eye test for children, carried out by optometrists experienced in paediatric vision care. The test assesses visual acuity, eye alignment, colour vision, and overall eye health. All children under 16 qualify for a free NHS-funded eye test, and Vision Express offers a range of children's frames designed for comfort and durability.",price:"Free (NHS funded)",duration:"20-30 minutes",nhsCovered:!0},{name:"Diabetic Eye Screening",description:"A specialised eye check for patients with diabetes, using digital retinal photography and OCT scanning to examine the blood vessels at the back of the eye for signs of diabetic retinopathy. Regular screening is critical for people with diabetes, as early detection of retinal changes can prevent serious vision loss.",price:"From £35",duration:"25 minutes",nhsCovered:!1}],bookingProcess:["Use the postcode search on eyetest.co.uk to find your closest Vision Express store","Compare services, prices, and patient reviews across local stores","Choose your appointment type — NHS eye test, private eye test, or advanced OCT health check","Pick a date and time that suits you from the available slots","Enter your details and confirm your booking — you will receive an email and text confirmation","Bring your current glasses, any contact lens details, and NHS exemption evidence to your appointment"],prosAndCons:{pros:["Access to an exclusive range of designer frames from the EssilorLuxottica portfolio","Advanced clinical technology including OCT scanning at most stores","30-day satisfaction guarantee and price match policy give confidence when buying","Bright, well-designed stores with large frame displays for easy browsing","Strong emphasis on clinical quality and qualified staff"],cons:["Private eye test prices are higher than budget competitors","Not currently available for booking through eyetest.co.uk","No hearing care services offered — optical only"]},faqs:[{q:"Does Vision Express offer a price match guarantee?",a:"Yes, Vision Express offers a price match guarantee on identical products. If you find the same frames and lenses cheaper at another optician, Vision Express will match the price. The product must be identical — same frame model, same lens type, and same lens coatings. You will need to provide proof of the competitor's price, such as a written quote or website listing."},{q:"What is Vision Express's 30-day satisfaction guarantee?",a:"Vision Express offers a 30-day satisfaction guarantee on all glasses purchased from their stores. If you are not completely happy with your new glasses within 30 days of collection, you can return them for an exchange or full refund. This applies to both frames and lenses and gives customers peace of mind when trying a new frame style or lens type."},{q:"Who owns Vision Express?",a:"Vision Express is owned by EssilorLuxottica, the world's largest eyewear company, formed from the 2018 merger of French lens manufacturer Essilor and Italian frame maker Luxottica. EssilorLuxottica also owns brands such as Ray-Ban, Oakley, Persol, and Oliver Peoples, as well as retail chains including Sunglass Hut and LensCrafters. This ownership gives Vision Express access to an extensive range of premium and designer frames."},{q:"How much do glasses cost at Vision Express?",a:"Glasses prices at Vision Express vary depending on the frame and lens choice. Complete glasses packages start from around £49 for basic single-vision prescriptions with budget frames. Designer frames typically range from £100 to £300 or more, and premium lens upgrades such as varifocals, anti-reflection coatings, and photochromic lenses are available at additional cost. NHS vouchers can be applied towards the total price for eligible patients."},{q:"Does Vision Express do contact lenses?",a:"Yes, Vision Express offers a full contact lens service, including initial assessments, trial fittings, and ongoing supply. They stock a wide range of lenses from major manufacturers including Johnson & Johnson (Acuvue), Alcon (Dailies, Air Optix), and CooperVision. Monthly contact lens subscription plans are available, which include regular check-ups and lens delivery to your home."},{q:"Can I book a Vision Express appointment through eyetest.co.uk?",a:"Vision Express is not currently available for direct booking through eyetest.co.uk. We include Vision Express on our platform so that customers can compare their services and prices with other opticians. To book an appointment, visit visionexpress.com or contact your local Vision Express store by phone. We hope to offer direct Vision Express booking in the future."},{q:"Does Vision Express offer free eye tests?",a:"Vision Express provides free NHS-funded eye tests for all eligible patients. Eligibility criteria include being under 16, over 60, receiving qualifying benefits, having diabetes or glaucoma, or having a close family member with glaucoma if you are over 40. If you are not eligible for an NHS test, private eye tests start from £30."},{q:"How long does it take to get glasses from Vision Express?",a:"Glasses from Vision Express typically take between 7 and 14 working days, depending on the complexity of your prescription and the lens options you choose. Simple single-vision prescriptions are usually at the faster end, while varifocals, high-index lenses, and specialty coatings may take a little longer. Vision Express will notify you by text or email when your glasses are ready for collection."}]},{slug:"asda-opticians",name:"ASDA Opticians",shortName:"ASDA",brandColor:"#78b530",description:"ASDA Opticians operates from within ASDA supermarkets across the UK, offering affordable eye care with the convenience of supermarket shopping. They are known for their straightforward pricing and competitive rates on both eye tests and eyewear. As part of the ASDA brand, they focus on delivering value without compromising on clinical quality, making eye care accessible to budget-conscious families.",services:["NHS Eye Tests","Private Eye Tests","Contact Lenses","Glasses","Children's Eye Tests"],storeCount:200,website:"https://opticians.asda.com",priceRange:"Free NHS / From £20 private",nhsAvailable:!0,available:!0,highlights:["Among the most affordable high-street options for glasses in the UK","Convenient locations inside ASDA supermarkets with free parking","Straightforward pricing with no hidden extras","Good selection of budget and mid-range frames for all ages"],founded:"2002",storeLocations:["london","croydon","bromley","kingston-upon-thames","ealing","brighton","reading","southampton","portsmouth","milton-keynes","slough","crawley","basingstoke","bristol","bath","exeter","plymouth","bournemouth","swindon","gloucester","cheltenham","taunton","cambridge","norwich","ipswich","colchester","chelmsford","luton","peterborough","southend-on-sea","bedford","birmingham","coventry","wolverhampton","stoke-on-trent","worcester","nottingham","leicester","derby","northampton","manchester","liverpool","chester","warrington","preston","blackpool","bolton","newcastle","sunderland","middlesbrough","leeds","sheffield","bradford","hull","doncaster","cardiff","swansea","newport"],history:"ASDA Opticians launched in 2002 as part of ASDA's broader strategy to offer a full range of health and lifestyle services within its supermarket stores. The concept followed the success of ASDA's pharmacy business, which had already demonstrated that customers were receptive to receiving healthcare services during their regular supermarket shop. By locating optical practices inside ASDA stores, the company was able to offer significantly lower prices than traditional high-street opticians, benefiting from shared premises, lower rent, and the supermarket's enormous footfall.\n\nThe optical business grew steadily through the 2000s and 2010s, expanding to around 200 locations across the UK. ASDA's parent company Walmart — which acquired ASDA in 1999 — brought considerable retail expertise and buying power, enabling the optical division to negotiate competitive prices on both frames and lenses. In 2021, ASDA was sold by Walmart to the Issa brothers and private equity firm TDR Capital, but the optical business continued to operate on the same value-focused model.\n\nToday, ASDA Opticians is known primarily for being one of the most affordable places to buy glasses on the UK high street. Their pricing is transparent and straightforward, with complete glasses packages starting from as little as £15 for basic frames with single-vision lenses. While they do not carry the designer brand ranges found at chains like Boots or Vision Express, they offer a solid selection of own-brand and mid-range frames, and their clinical services meet the same regulatory standards as any other registered optician. Free parking at ASDA supermarkets is an added convenience that many customers value.",detailedServices:[{name:"NHS Eye Test",description:"A full NHS-funded eye examination for eligible patients. The test covers visual acuity, refraction, intraocular pressure measurement, and a health examination of the eyes. ASDA optometrists are fully qualified and registered with the General Optical Council, providing the same standard of clinical care as any high-street optician.",price:"Free (if eligible)",duration:"20-25 minutes",nhsCovered:!0},{name:"Private Eye Test",description:"A comprehensive eye examination for patients who do not qualify for the NHS-funded test. ASDA offers one of the lowest-priced private eye tests on the high street. The examination includes refraction, eye health checks, and a prescription for glasses or contact lenses if needed.",price:"From £20",duration:"20-25 minutes",nhsCovered:!1},{name:"Contact Lens Consultation",description:"An initial assessment to determine your suitability for contact lenses. Includes corneal measurements, tear film assessment, and a trial fitting with appropriate lenses. ASDA offers a range of contact lenses from major manufacturers at competitive prices, and can set up a regular supply plan for ongoing wearers.",price:"From £25",duration:"25-35 minutes",nhsCovered:!1},{name:"Children's Eye Test",description:"A free NHS eye test for children under 16, adapted for younger patients. ASDA optometrists use age-appropriate techniques and charts to assess children's vision, and the store stocks a range of children's frames available free or at a low cost with the NHS voucher.",price:"Free (NHS funded)",duration:"20-30 minutes",nhsCovered:!0},{name:"Glasses Dispensing",description:"Once you have your prescription, ASDA's dispensing opticians will help you choose frames and lenses. ASDA is known for extremely competitive pricing, with complete pairs of glasses starting from £15 for basic frames with single-vision lenses. Lens upgrades such as anti-reflection coatings and thinner lenses are available at additional cost but remain competitively priced.",price:"From £15 (complete pair)",duration:"15-20 minutes",nhsCovered:!1}],bookingProcess:["Search for your nearest ASDA Opticians by entering your postcode on eyetest.co.uk","View available appointment types and compare prices with other local opticians","Choose a date and time that fits your schedule — evening and weekend slots are available at most stores","Enter your details and confirm your booking","Receive confirmation by email with directions and parking information for your ASDA store","Attend your appointment — combine your eye test with your regular supermarket shop for convenience"],prosAndCons:{pros:["Among the lowest prices for glasses on the UK high street, with complete pairs from £15","Free parking at ASDA supermarket locations makes visits easy and stress-free","Transparent, straightforward pricing with no pressure to upsell","Convenient to combine eye care with your regular weekly shop"],cons:["Limited designer and premium frame selection compared to dedicated opticians","No OCT scanning or advanced eye health screening available at most locations","No hearing care services offered"]},faqs:[{q:"How much do glasses cost at ASDA Opticians?",a:"ASDA Opticians offers some of the most competitive prices on the high street. Complete glasses — frames with single-vision lenses — start from as little as £15. Mid-range frames typically cost between £30 and £80, and lens upgrades such as anti-reflection coatings, thinner high-index lenses, and varifocals are available at additional cost but remain cheaper than most competitors. NHS vouchers can be applied to reduce costs further for eligible patients."},{q:"Are ASDA eye tests as good as other opticians?",a:"Yes. All ASDA optometrists are fully qualified and registered with the General Optical Council, which is the same regulatory body that governs every optician in the UK. The clinical quality of the eye test is the same standard as you would receive at any other registered opticians. The main difference is that ASDA offers fewer premium add-on services such as OCT scanning, and the frame selection focuses more on value than designer brands."},{q:"Can I get free glasses at ASDA with an NHS voucher?",a:"Yes, ASDA Opticians accepts NHS optical vouchers. If you are eligible for an NHS voucher — which includes children under 16, people on qualifying benefits, and those with complex prescriptions — it can be applied towards the cost of your glasses. Because ASDA's frame prices are very competitive, many patients find that the NHS voucher covers the full cost of a basic pair of glasses."},{q:"Does ASDA Opticians offer contact lenses?",a:"Yes, ASDA Opticians provides contact lens assessments, fittings, and ongoing supply. They stock lenses from major manufacturers at competitive prices. Monthly supply plans are available for regular contact lens wearers, though the range may be narrower than at specialist contact lens providers."},{q:"Is there free parking at ASDA Opticians?",a:"Yes, one of the significant advantages of ASDA Opticians is free parking. All ASDA stores provide free car parking for customers, which means you can drive to your eye test without worrying about parking charges or time limits. This is a notable benefit compared to high-street opticians in town centres where parking can be expensive and difficult to find."},{q:"Does ASDA Opticians do home visits?",a:"No, ASDA Opticians does not currently offer a home visit eye testing service. All eye tests are carried out at ASDA supermarket locations. If you or a family member cannot travel to a store for an eye test, you may want to consider opticians that do offer home visits, such as Specsavers or Scrivens."},{q:"How often should I visit ASDA Opticians for an eye test?",a:"The general recommendation is an eye test every two years for most adults, or annually if you are over 70, diabetic, have a family history of glaucoma, or have been advised by your optometrist to come back sooner. Children should have their eyes tested annually. Regular tests are important not just for keeping your prescription up to date but for detecting eye health issues early."},{q:"What are the opening hours for ASDA Opticians?",a:"ASDA Opticians generally follow the opening hours of the ASDA supermarket they are located in, which typically means long opening hours including evenings and weekends. Most stores are open Monday to Saturday from around 9am to 8pm or 9pm, and Sunday from around 10am to 4pm. Hours may vary by location, so check your local store's specific times when booking."}]},{slug:"leightons",name:"Leightons Opticians & Hearing Care",shortName:"Leightons",brandColor:"#1e3a5f",description:"Leightons is a family-owned opticians and hearing care provider established in 1928, operating primarily across southern England. They are known for their premium, personalised service and investment in the latest clinical technology, including advanced OCT scanning and myopia management for children. Leightons holds a reputation for thorough eye examinations that go well beyond the standard NHS sight test.",services:["NHS Eye Tests","Private Eye Tests","Contact Lenses","Glasses","Hearing Tests","Children's Eye Tests","OCT Scan","Diabetic Screening","Home Visits"],storeCount:35,website:"https://www.leightons.co.uk",priceRange:"Free NHS / From £39 private",nhsAvailable:!0,available:!0,highlights:["Family-owned since 1928 with a strong reputation for clinical excellence","Ultimate Eye Examination includes OCT, visual fields, and detailed health screening","Specialist myopia management service for children","Combined opticians and hearing care under one roof"],founded:"1928",storeLocations:["london","croydon","bromley","kingston-upon-thames","richmond","ealing","brighton","reading","oxford","guildford","canterbury","southampton","portsmouth","basingstoke","chichester","worthing","tunbridge-wells","crawley","slough","chelmsford","st-albans"],history:'Leightons Opticians was founded in 1928 by Henry Oscar Leighton in the town of Marlow, Buckinghamshire. From its earliest days, the practice distinguished itself through meticulous attention to patient care and a commitment to investing in the best available clinical equipment. The business remained in the Leighton family for decades, gradually expanding across the Home Counties and southern England while maintaining the personal, community-focused ethos that had defined the original practice.\n\nThroughout the latter half of the twentieth century, Leightons grew steadily, opening new branches in affluent towns across Surrey, Hampshire, Berkshire, and Sussex. The company was an early adopter of new optical technology, introducing computerised eye testing equipment and OCT scanning before many of its competitors. In the 2000s, Leightons expanded its services to include hearing care, recognising the overlap between vision and hearing health in its predominantly older patient demographic. The combined opticians-and-audiologists model allowed patients to manage both aspects of their sensory health in a single appointment.\n\nToday, Leightons operates approximately 35 practices across southern England and remains privately owned and family-run. The company has developed a strong reputation for its "Ultimate Eye Examination" — a comprehensive assessment that includes OCT scanning, visual field testing, digital retinal photography, and a detailed consultation that typically lasts 45 minutes to an hour. Leightons also offers a specialist myopia management service for children, using the latest evidence-based interventions to slow the progression of short-sightedness. The brand positions itself firmly at the premium end of the market, prioritising clinical depth and personalised care over volume and price competition.',detailedServices:[{name:"NHS Eye Test",description:"A standard NHS-funded sight test for eligible patients. Leightons provides a thorough examination within the NHS framework, including visual acuity assessment, refraction, and eye health checks. Even within the NHS test, Leightons optometrists take time to discuss findings and answer questions fully.",price:"Free (if eligible)",duration:"20-25 minutes",nhsCovered:!0},{name:"Private Eye Test",description:"A comprehensive private eye examination that allows more time for discussion and assessment than the standard NHS test. Leightons' private test includes detailed refraction, binocular vision assessment, and a thorough examination of eye health using slit lamp biomicroscopy.",price:"From £39",duration:"30 minutes",nhsCovered:!1},{name:"Ultimate Eye Examination",description:"Leightons' flagship eye examination — a thorough, technology-led assessment that goes far beyond a standard sight test. It includes OCT scanning of the retina and optic nerve, wide-field digital retinal photography, visual field testing, and a detailed discussion of your eye health and visual needs. This examination is designed to detect conditions such as glaucoma, macular degeneration, and diabetic retinopathy at the earliest possible stage.",price:"From £79",duration:"45-60 minutes",nhsCovered:!1},{name:"Contact Lens Consultation",description:"A specialist appointment for patients considering contact lenses or those wanting to switch types. Leightons offers a wide range of contact lenses including daily disposables, monthly lenses, toric lenses for astigmatism, and multifocal lenses. The consultation includes detailed corneal mapping, tear film analysis, and a comprehensive trial fitting.",price:"From £50",duration:"40-50 minutes",nhsCovered:!1},{name:"Myopia Management for Children",description:"A specialist service designed to slow the progression of myopia (short-sightedness) in children. Leightons uses evidence-based interventions including MiSight contact lenses, Miyosmart spectacle lenses, and orthokeratology (overnight corneal reshaping lenses). The service includes an initial assessment, ongoing monitoring, and regular reviews to track progression.",price:"From £60 (initial assessment)",duration:"45 minutes (initial), 30 minutes (follow-up)",nhsCovered:!1},{name:"Hearing Assessment",description:"A comprehensive hearing test carried out by a qualified audiologist at selected Leightons branches. The assessment includes an ear health check, pure tone audiometry, and speech-in-noise testing. If hearing loss is detected, the audiologist will discuss hearing aid options from leading manufacturers including Phonak, Oticon, and Widex.",price:"Free",duration:"45 minutes",nhsCovered:!1},{name:"Children's Eye Test",description:"A specialist eye test for children, using age-appropriate techniques and a gentle, patient approach. Leightons optometrists are experienced in working with young children and will check for common childhood vision issues including lazy eye, squint, and focusing difficulties. All children under 16 qualify for a free NHS eye test.",price:"Free (NHS funded)",duration:"25-30 minutes",nhsCovered:!0},{name:"Diabetic Eye Check",description:"A specialist eye examination for patients with diabetes, incorporating OCT scanning and digital retinal photography to closely monitor the health of the blood vessels at the back of the eye. Leightons recommends this annually for all patients with type 1 or type 2 diabetes, as early detection of diabetic retinopathy is essential for preserving vision.",price:"From £45",duration:"30 minutes",nhsCovered:!1}],bookingProcess:["Find your nearest Leightons branch by searching with your postcode on eyetest.co.uk","Browse available services — from standard NHS tests to the Ultimate Eye Examination and myopia management","Select your preferred appointment type, date, and time","Provide your details and any relevant medical history or special requirements","Receive a confirmation email with directions to your branch and guidance on what to bring","Attend your appointment — allow extra time if you wish to browse the frame collection afterwards"],prosAndCons:{pros:["Exceptionally thorough Ultimate Eye Examination with advanced OCT and visual field testing","Family-owned since 1928 with a genuine focus on patient relationships and continuity of care","Specialist myopia management programme for children using the latest interventions","Combined opticians and hearing care for convenient single-location appointments","Premium frame selection including independent and niche designers not found at chain opticians"],cons:["Higher prices than budget and mainstream chain opticians","Limited geographic coverage — branches only in southern England","Smaller scale means fewer available appointment slots at busy times"]},faqs:[{q:"What is the Ultimate Eye Examination at Leightons?",a:"The Ultimate Eye Examination is Leightons' most comprehensive eye health assessment. It goes well beyond a standard sight test, incorporating OCT (Optical Coherence Tomography) scanning, wide-field digital retinal photography, visual field testing, and an extended consultation with your optometrist. The examination typically lasts between 45 minutes and an hour and is designed to detect eye conditions at the earliest possible stage. It is particularly recommended for patients with a family history of eye disease, those over 40, and anyone wanting the most thorough possible check of their eye health."},{q:"Does Leightons offer myopia management for children?",a:"Yes, Leightons is one of the leading providers of myopia management for children in the UK. Their programme uses evidence-based treatments to slow the progression of short-sightedness, including MiSight daily contact lenses, Miyosmart spectacle lenses, and orthokeratology (overnight corneal reshaping lenses). The service begins with a detailed assessment of the child's myopia and risk factors, followed by a tailored treatment plan with regular monitoring appointments to track progress."},{q:"Where are Leightons branches located?",a:"Leightons operates approximately 35 branches across southern England, concentrated in the Home Counties and along the south coast. You will find Leightons practices in areas including London, Surrey, Hampshire, Berkshire, Sussex, Kent, and Buckinghamshire. They do not currently have branches in the Midlands, the North of England, Scotland, Wales, or Northern Ireland."},{q:"Is Leightons more expensive than Specsavers or Boots?",a:"Leightons is positioned at the premium end of the market, and their prices are generally higher than mainstream chains like Specsavers, Boots, or ASDA. However, the higher cost reflects longer appointment times, more advanced diagnostic technology, and a greater depth of clinical assessment. Many patients who have switched to Leightons report that the difference in the thoroughness and quality of the examination justifies the additional cost. NHS eye tests are available free to eligible patients, just as at any other optician."},{q:"Does Leightons offer hearing aids?",a:"Yes, many Leightons branches provide a full audiology service alongside their optical care. They work with leading hearing aid manufacturers including Phonak, Oticon, Widex, and Signia, offering a range of devices from discreet in-ear models to powerful behind-the-ear aids. Hearing assessments are free, and audiologists will explain all available options, including the differences between NHS-funded and private hearing aids."},{q:"Can I get an NHS eye test at Leightons?",a:"Yes, Leightons provides free NHS-funded eye tests for all eligible patients. This includes children under 16, adults over 60, people receiving certain means-tested benefits, and patients with specific medical conditions such as diabetes or glaucoma. If you also want the enhanced tests included in the Ultimate Eye Examination — such as OCT scanning and visual fields — these are available at an additional cost."},{q:"How do I book an appointment at Leightons through eyetest.co.uk?",a:"You can search for your nearest Leightons branch by entering your postcode on eyetest.co.uk. The results will show you available appointment types, prices, and time slots. Select the service you want, pick a convenient date and time, enter your details, and confirm the booking. You will receive an email confirmation with all the information you need for your visit."},{q:"What frame brands does Leightons stock?",a:"Leightons carries a curated selection of premium and independent frame brands that you are unlikely to find at the larger chain opticians. Their collections typically include brands such as Tom Ford, Lindberg, Mykita, Etnia Barcelona, and Face a Face, alongside more widely available names like Ray-Ban and Oliver Peoples. Each branch has its own carefully chosen selection, so the range may vary between locations."}]},{slug:"rawlings",name:"Rawlings Opticians",shortName:"Rawlings",brandColor:"#8b2252",description:"Rawlings Opticians is a long-established independent chain based in South East England, known for its community-focused approach and dedicated patient care. With around ten practices, they offer a more personal alternative to the larger chains, combining traditional optometry values with modern diagnostic equipment. Rawlings has built a loyal patient base through consistently high standards of clinical care and customer service.",services:["NHS Eye Tests","Private Eye Tests","Contact Lenses","Glasses","Children's Eye Tests","OCT Scan","Diabetic Screening"],storeCount:10,website:"https://www.rawlings.co.uk",priceRange:"Free NHS / From £30 private",nhsAvailable:!0,available:!0,highlights:["Independent, community-focused practices in South East England","Personal service with longer appointment times than larger chains","Modern diagnostic technology including OCT retinal scanning","Strong patient loyalty with a focus on continuity of care"],founded:"1898",storeLocations:["london","bromley","croydon","maidstone","tunbridge-wells","crawley","chichester","worthing","canterbury","brighton"],history:"Rawlings Opticians was founded in 1898, making it one of the oldest optical practices still operating in the United Kingdom. The business began as a single practice in the South East of England at a time when optometry was still a relatively young profession, and spectacles were only beginning to become widely available to the general public. From the outset, the Rawlings name became associated with careful, unhurried patient care and a deep commitment to clinical standards — values that have remained at the heart of the business for over 125 years.\n\nThroughout the twentieth century, Rawlings expanded gradually, opening additional practices across Kent, Sussex, and South London. Unlike many optical businesses that pursued aggressive national expansion, Rawlings chose to grow slowly and organically, ensuring that each new practice maintained the same standards of care that had defined the original. This measured approach to growth meant that Rawlings practices developed strong roots in their local communities, with many patients returning for decades and bringing successive generations of their families.\n\nToday, Rawlings operates approximately ten practices across the South East of England. The business has invested in modern clinical technology, including OCT scanning and digital retinal photography, while preserving the longer appointment times and personal attention that distinguish it from the high-volume national chains. Rawlings remains an independent group, and its optometrists take pride in knowing their patients by name and maintaining detailed records that allow genuine continuity of care from one appointment to the next. In an era of corporate consolidation in the optical industry, Rawlings represents an increasingly rare example of a truly independent, heritage opticians group.",detailedServices:[{name:"NHS Eye Test",description:"A comprehensive NHS-funded eye examination for eligible patients. Rawlings optometrists provide a thorough assessment including visual acuity, refraction, eye pressure measurement, and a detailed examination of the health of your eyes. The longer appointment times at Rawlings mean that even NHS tests are unhurried and thorough.",price:"Free (if eligible)",duration:"25-30 minutes",nhsCovered:!0},{name:"Private Eye Test",description:"A detailed private eye examination for patients not eligible for NHS funding. The test includes a comprehensive refraction, binocular vision assessment, eye health examination, and a discussion of your visual needs. Rawlings' private tests benefit from longer appointment slots, allowing the optometrist to take extra time with each patient.",price:"From £30",duration:"30-35 minutes",nhsCovered:!1},{name:"Enhanced Eye Examination with OCT",description:"A premium eye examination incorporating OCT (Optical Coherence Tomography) scanning to provide a detailed view of the layers of the retina and optic nerve head. This scan can detect early signs of glaucoma, macular degeneration, and other conditions before they cause noticeable symptoms. Rawlings recommends this test as a baseline for all patients over 25.",price:"From £55",duration:"35-40 minutes",nhsCovered:!1},{name:"Contact Lens Fitting",description:"A specialist appointment for patients wanting to start wearing contact lenses or switch to a different type. The fitting includes corneal topography, tear film assessment, and a trial lens fitting. Rawlings optometrists take the time to ensure you are fully comfortable with lens insertion and removal before leaving the practice.",price:"From £40",duration:"35-45 minutes",nhsCovered:!1},{name:"Children's Eye Test",description:"A gentle, child-friendly eye examination using age-appropriate techniques. Rawlings optometrists are experienced with children of all ages and create a relaxed environment to help young patients feel at ease. The test checks for common childhood vision issues including amblyopia (lazy eye), squint, and refractive errors. All children under 16 receive a free NHS-funded test.",price:"Free (NHS funded)",duration:"25-30 minutes",nhsCovered:!0},{name:"Diabetic Eye Examination",description:"A specialist examination for patients with diabetes, using digital retinal photography and OCT scanning to examine the blood vessels at the back of the eye. Rawlings recommends this annually for all diabetic patients to monitor for signs of diabetic retinopathy, which can be treated effectively if caught early.",price:"From £40",duration:"25-30 minutes",nhsCovered:!1}],bookingProcess:["Search for your nearest Rawlings practice by entering your postcode on eyetest.co.uk","Compare available appointments and services at nearby Rawlings branches","Select your preferred eye test type, date, and time from available slots","Enter your personal details and any relevant medical information","Receive an email confirmation with your appointment details and practice directions","Attend your appointment — Rawlings practices have a relaxed atmosphere, so there is no need to rush"],prosAndCons:{pros:["Over 125 years of heritage and a strong reputation for clinical excellence","Longer appointment times than chain opticians allow for genuinely thorough examinations","Community-focused independent practices where staff know patients by name","Modern diagnostic technology including OCT scanning in a traditional, personal setting"],cons:["Very limited geographic coverage — only available in parts of South East England","Smaller frame selection than the large national chains","Fewer appointment slots available due to longer appointment durations"]},faqs:[{q:"How old is Rawlings Opticians?",a:"Rawlings Opticians was founded in 1898, making it one of the oldest optical practices still operating in the UK. The business has been providing eye care for over 125 years, spanning the entire modern history of optometry in Britain. This heritage is a source of considerable pride for the company, and long-standing patient relationships — sometimes spanning three or four generations of the same family — are a hallmark of the Rawlings experience."},{q:"Where are Rawlings Opticians located?",a:"Rawlings operates approximately ten practices across South East England, concentrated in Kent, Sussex, Surrey, and South London. Specific locations include Bromley, Croydon, Maidstone, Tunbridge Wells, Crawley, Chichester, Worthing, Canterbury, and Brighton. They do not have branches outside the South East of England."},{q:"Is Rawlings an independent opticians?",a:"Yes, Rawlings is an independent opticians group. Unlike the large national chains that are owned by multinational corporations, Rawlings operates as a standalone business. This independence allows them to make decisions based on what is best for their patients rather than corporate targets, and to curate their own selection of frames and lenses. Their independent status is a key part of their identity and appeal."},{q:"Do Rawlings appointments take longer than other opticians?",a:"Yes, Rawlings is known for allocating longer appointment times than most chain opticians. A standard eye test at Rawlings typically takes 25 to 35 minutes, compared to 20 to 25 minutes at most chains. This extra time allows the optometrist to carry out a more thorough examination and to discuss findings and recommendations in greater detail. Many patients who have moved to Rawlings from chain opticians specifically cite the longer appointments as a reason for switching."},{q:"Does Rawlings offer OCT scanning?",a:"Yes, Rawlings offers OCT (Optical Coherence Tomography) scanning at their practices. This advanced imaging technology produces detailed cross-section images of the retina, allowing early detection of conditions such as glaucoma and macular degeneration. The OCT scan is available as part of the enhanced eye examination and is recommended as a baseline for patients over 25."},{q:"Can I get an NHS eye test at Rawlings?",a:"Yes, Rawlings provides free NHS-funded eye tests for all eligible patients. Eligibility includes children under 16, adults over 60, people on qualifying benefits, and those with certain medical conditions. Even within the NHS-funded test, Rawlings optometrists provide a thorough and unhurried examination. If you would like additional screening such as OCT, this can be added for an extra fee."}]},{slug:"scrivens",name:"Scrivens Opticians & Hearing Care",shortName:"Scrivens",brandColor:"#c62828",description:"Scrivens is a well-established family-run opticians and hearing care group with around 100 branches across the Midlands, South West, and South of England. Founded in 1938, they combine the reach of a national chain with the personal touch of a family business. Scrivens is particularly well regarded for their hearing care services alongside traditional optical care, and they have been a trusted name in communities across their regions for decades.",services:["NHS Eye Tests","Private Eye Tests","Contact Lenses","Glasses","Hearing Tests","Home Visits","Children's Eye Tests","OCT Scan"],storeCount:100,website:"https://www.scrivens.com",priceRange:"Free NHS / From £25 private",nhsAvailable:!0,available:!0,highlights:["Family-run business since 1938 with genuine community presence","Combined opticians and hearing care across all branches","Home visit service for elderly or housebound patients","Consistently rated highly for personal service and patient care"],founded:"1938",storeLocations:["birmingham","coventry","wolverhampton","stoke-on-trent","worcester","nottingham","leicester","derby","northampton","hereford","bristol","bath","exeter","plymouth","gloucester","cheltenham","swindon","bournemouth","taunton","torquay","southampton","portsmouth","reading","oxford","london","slough","luton","bedford","milton-keynes","cambridge"],history:"Scrivens Opticians was founded in 1938 by Douglas Scrivens, who opened his first optical practice in the West Midlands. The business began modestly, offering eye tests and spectacles to the local community, but the quality of care and personal attention it provided quickly built a loyal customer base. Even during the difficult years of the Second World War, the practice continued to serve its patients, and by the post-war period, Douglas Scrivens had established a reputation that extended well beyond his immediate neighbourhood.\n\nThe company expanded steadily through the second half of the twentieth century, opening new branches across the Midlands, the South West, and the South of England. In the 1980s, Scrivens made the strategic decision to add hearing care services to its optical practices, recognising the natural overlap between the two areas of sensory health. This dual-service model proved popular with patients, particularly older customers who could have both their eyes and hearing checked in a single visit. The hearing care division grew to become a significant part of the business, and today Scrivens is one of the largest independent providers of hearing aids in the UK.\n\nScrivens remains a family-run business to this day, with the founding family maintaining an active role in the company. With around 100 branches, the group is large enough to invest in modern clinical equipment and professional training, yet small enough that individual branches retain a genuine sense of community. Scrivens is also one of the few optical groups in the UK to offer a comprehensive domiciliary (home visit) service, sending optometrists and audiologists to patients who are unable to travel to a branch. This service is particularly valued by elderly and housebound patients in the communities Scrivens serves.",detailedServices:[{name:"NHS Eye Test",description:"A full NHS-funded eye examination carried out by a qualified Scrivens optometrist. The test includes visual acuity assessment, refraction, intraocular pressure measurement, and a thorough examination of the internal and external health of the eyes. Scrivens is known for providing unhurried, personal attention even within the NHS test framework.",price:"Free (if eligible)",duration:"20-25 minutes",nhsCovered:!0},{name:"Private Eye Test",description:"A comprehensive eye examination for patients who do not qualify for NHS-funded testing. The test covers refraction, binocular vision assessment, eye pressure, and eye health examination. Scrivens' private test is competitively priced and provides the same thorough clinical assessment as the NHS test.",price:"From £25",duration:"25-30 minutes",nhsCovered:!1},{name:"Enhanced Eye Examination with OCT",description:"An extended eye examination that includes OCT (Optical Coherence Tomography) scanning, providing detailed cross-section images of the retina and optic nerve. This advanced scan can reveal early signs of conditions such as glaucoma, macular degeneration, and diabetic retinopathy. Available at most Scrivens branches equipped with OCT technology.",price:"From £35",duration:"30-35 minutes",nhsCovered:!1},{name:"Home Visit Eye Test",description:"A full eye test carried out in the patient's own home by a Scrivens domiciliary optometrist. This service is available for patients who cannot travel to a branch due to illness, disability, or mobility issues. The optometrist brings portable equipment and a selection of frames, so glasses can be ordered during the visit. NHS-funded home visits are free for eligible patients.",price:"Free (NHS eligible) / From £25 (private)",duration:"30-40 minutes",nhsCovered:!0},{name:"Hearing Assessment",description:"A comprehensive hearing test carried out by a qualified Scrivens audiologist. The assessment includes an ear examination, pure tone audiometry, and speech discrimination testing. If hearing loss is detected, the audiologist will discuss hearing aid options, including both NHS-funded and private digital hearing aids from leading manufacturers.",price:"Free",duration:"30-45 minutes",nhsCovered:!1},{name:"Contact Lens Fitting",description:"An initial assessment for patients considering contact lenses, including corneal measurements, tear film evaluation, and a trial fitting. Scrivens offers a range of contact lens types from major manufacturers, and ongoing supply plans are available for regular wearers.",price:"From £30",duration:"30-40 minutes",nhsCovered:!1},{name:"Children's Eye Test",description:"A friendly, age-appropriate eye test for children using picture charts, matching tests, and retinoscopy. All children under 16 are entitled to a free NHS eye test, and Scrivens stocks a range of children's frames available under the NHS voucher scheme. Scrivens staff are experienced in working with young children to make the experience comfortable and positive.",price:"Free (NHS funded)",duration:"20-30 minutes",nhsCovered:!0}],bookingProcess:["Enter your postcode on eyetest.co.uk to find Scrivens branches in your area","Compare services and availability — Scrivens offers eye tests, hearing tests, and home visits","Select your preferred appointment type and choose a convenient date and time","Provide your personal details and let us know if you have mobility or accessibility requirements","Receive a confirmation email with your appointment details and branch address","Attend your appointment — if you need a home visit, a Scrivens optometrist will come to you at the booked time"],prosAndCons:{pros:["Family-run business with a genuine personal touch and strong community roots","Combined optical and hearing care means you can address both in one visit","Comprehensive home visit service for housebound and elderly patients","Competitive pricing with a focus on value rather than aggressive upselling","Over 80 years of experience in eye care and decades of hearing care expertise"],cons:["Geographic coverage is limited to the Midlands, South West, and South of England","Designer frame selection is smaller than at chains like Boots or Vision Express","Some branches may not yet have OCT scanning equipment installed"]},faqs:[{q:"Does Scrivens offer home eye tests?",a:"Yes, Scrivens provides a comprehensive home visit service for patients who are unable to travel to a branch due to illness, disability, or mobility issues. A qualified Scrivens optometrist will visit your home with portable testing equipment and a selection of frames, so you can have your eyes tested and order glasses without leaving the house. If you qualify for an NHS-funded eye test, the home visit is also free. This is one of Scrivens' most valued services, particularly for elderly patients."},{q:"Is Scrivens a family business?",a:"Yes, Scrivens was founded in 1938 by Douglas Scrivens and remains family-run to this day. The founding family continues to be actively involved in the management of the business. This family ownership is reflected in the culture of the company, which prioritises personal relationships with patients and a community-focused approach to eye care and hearing care."},{q:"Does Scrivens do hearing tests?",a:"Yes, hearing care is a core part of the Scrivens service. Every Scrivens branch offers hearing assessments, which are provided free of charge by qualified audiologists. If hearing loss is detected, Scrivens can supply both NHS-funded hearing aids (where eligible) and private digital hearing aids from leading manufacturers. The combination of optical and hearing care under one roof is a significant convenience for patients."},{q:"Where are Scrivens branches located?",a:"Scrivens operates approximately 100 branches across the Midlands, the South West, and the South of England. Concentrations include the West Midlands (Birmingham, Coventry, Wolverhampton), the East Midlands (Nottingham, Leicester, Derby), the South West (Bristol, Bath, Exeter, Plymouth), and parts of southern England (Southampton, Portsmouth, Reading, Oxford). They do not currently have branches in the North of England, Scotland, Wales, or Northern Ireland."},{q:"How much do glasses cost at Scrivens?",a:"Scrivens offers a range of frames at competitive prices. Complete glasses — frames with single-vision lenses — start from around £49. The selection includes a mix of own-brand frames and recognised mid-range brands. Lens upgrades such as anti-reflection coatings, varifocals, and thinner lenses are available at additional cost. NHS optical vouchers are accepted and can be put towards the cost of glasses for eligible patients."},{q:"Can I get an NHS eye test at Scrivens?",a:"Yes, Scrivens provides free NHS-funded eye tests for all eligible patients. Eligibility is the same as at any UK optician — children under 16, adults over 60, those on qualifying benefits, and patients with certain medical conditions. Scrivens also provides NHS-funded home visits for eligible patients who cannot attend a branch in person."},{q:"Does Scrivens offer hearing aids on the NHS?",a:"Yes, Scrivens is contracted to provide NHS hearing aids at many of its branches. If you are referred by your GP or if a Scrivens audiologist identifies hearing loss, you may be eligible for a free NHS digital hearing aid. Private hearing aids are also available for patients who want a wider choice of styles and technology levels, with prices starting from around £395 per aid."},{q:"How do I book a home visit with Scrivens?",a:"You can arrange a Scrivens home visit by searching for your nearest branch on eyetest.co.uk and selecting the home visit option when booking, or by contacting your local Scrivens branch directly. You will need to confirm that you or the person requiring the test is unable to attend the branch unaccompanied. Home visits are available for both eye tests and hearing assessments."}]},{slug:"bayfields",name:"Bayfields Opticians & Audiologists",shortName:"Bayfields",brandColor:"#4a148c",description:"Bayfields is a growing group of independent opticians and audiologists with practices across England and Wales. They have expanded steadily by acquiring established independent practices and retaining their local character, staff, and patient relationships. Bayfields focuses on clinical excellence and offers enhanced eye examinations alongside standard NHS sight tests, with a commitment to investing in advanced diagnostic technology across their network.",services:["NHS Eye Tests","Private Eye Tests","Contact Lenses","Glasses","Hearing Tests","Children's Eye Tests","OCT Scan","Diabetic Screening"],storeCount:60,website:"https://www.bayfields.com",priceRange:"Free NHS / From £30 private",nhsAvailable:!0,available:!0,highlights:["Growing network that preserves the identity of acquired independent practices","Enhanced eye examinations with the latest diagnostic equipment","Combined optical and audiology services at many locations","Strong focus on staff retention and continuity of patient care"],founded:"2015",storeLocations:["london","croydon","brighton","reading","oxford","guildford","southampton","portsmouth","milton-keynes","basingstoke","bristol","bath","exeter","plymouth","bournemouth","swindon","gloucester","cheltenham","cambridge","norwich","ipswich","colchester","chelmsford","luton","birmingham","coventry","wolverhampton","worcester","nottingham","leicester","derby","northampton","cardiff","swansea","newport"],history:"Bayfields Opticians & Audiologists was established in 2015 as a new kind of optical group with a distinctive acquisition strategy. Rather than building new stores from scratch, Bayfields set out to acquire well-established independent opticians practices across England and Wales, preserving their local identities, retaining their experienced staff, and maintaining the patient relationships that had been built up over years or even decades. The founding vision was that independent opticians offered a level of care and personal attention that patients valued highly, but that many independent owners were reaching retirement age and needed a viable succession plan.\n\nThe group grew rapidly through the late 2010s and into the 2020s, acquiring practices in a wide range of towns and cities across England and Wales. Each acquired practice continued to operate under its existing name in many cases, with Bayfields providing back-office support, group purchasing power, and investment in clinical technology. This model allowed the group to maintain the trusted local feel of each practice while bringing the benefits of scale — including access to the latest OCT scanners, staff training programmes, and audiological equipment.\n\nToday, Bayfields operates approximately 60 practices and continues to grow. The group has invested heavily in adding audiology services to practices that previously offered only optical care, creating a combined opticians-and-audiologists model similar to that of Scrivens and Leightons. Bayfields positions itself as a clinically focused group that prioritises patient outcomes over volume, and its acquisition model has made it an important player in the consolidation of the UK independent optical sector.",detailedServices:[{name:"NHS Eye Test",description:"A standard NHS-funded eye examination for eligible patients. Bayfields optometrists conduct a thorough assessment including visual acuity, refraction, eye pressure measurement, and a detailed examination of eye health. The unhurried, personal approach that characterised each practice before it joined the Bayfields group is maintained.",price:"Free (if eligible)",duration:"20-25 minutes",nhsCovered:!0},{name:"Private Eye Test",description:"A comprehensive private eye examination that includes refraction, binocular vision assessment, and a thorough evaluation of the internal and external health of the eyes. Bayfields private tests offer more time for discussion of your visual needs and lifestyle requirements than the NHS-funded test.",price:"From £30",duration:"25-30 minutes",nhsCovered:!1},{name:"Enhanced Eye Examination with OCT",description:"An advanced eye examination incorporating OCT (Optical Coherence Tomography) scanning. This non-invasive scan produces detailed images of the retina and optic nerve, enabling early detection of conditions such as glaucoma, macular degeneration, and diabetic retinopathy. Bayfields has invested in OCT technology across its network, making this service available at most practices.",price:"From £40",duration:"30-40 minutes",nhsCovered:!1},{name:"Contact Lens Assessment",description:"An initial appointment to assess your suitability for contact lenses. Includes corneal topography, tear film analysis, and a trial fitting with the most appropriate lens type for your eyes and lifestyle. Bayfields practices stock a full range of contact lenses from daily disposables to specialist toric and multifocal options.",price:"From £35",duration:"30-40 minutes",nhsCovered:!1},{name:"Hearing Assessment",description:"A comprehensive hearing evaluation carried out by a qualified audiologist at Bayfields practices with audiology services. The assessment includes an ear health check using an otoscope, pure tone audiometry, and speech-in-noise testing. If hearing loss is identified, the audiologist will recommend appropriate hearing aids from a range of leading manufacturers.",price:"Free",duration:"30-45 minutes",nhsCovered:!1},{name:"Children's Eye Test",description:"A child-friendly eye examination using age-appropriate techniques, carried out by optometrists experienced in paediatric vision assessment. All children under 16 receive a free NHS-funded test. Bayfields practices typically offer a good range of children's frames, including options covered by the NHS voucher.",price:"Free (NHS funded)",duration:"20-30 minutes",nhsCovered:!0},{name:"Diabetic Eye Check",description:"A specialist examination for diabetic patients incorporating digital retinal photography and, where available, OCT scanning. This check focuses on detecting signs of diabetic retinopathy and other diabetes-related changes in the eye. Bayfields recommends annual diabetic eye checks in addition to the national NHS diabetic eye screening programme.",price:"From £35",duration:"25-30 minutes",nhsCovered:!1}],bookingProcess:["Search for your nearest Bayfields practice by entering your postcode on eyetest.co.uk","Browse available services — many Bayfields locations offer both optical and hearing care","Choose your preferred appointment type, date, and time from the available slots","Provide your contact details and any relevant health information","Receive a booking confirmation email with directions to your local practice","Attend your appointment at the local Bayfields practice — you will be seen by staff who know the practice and community well"],prosAndCons:{pros:["Retains the personal, community-focused character of each acquired independent practice","Investment in OCT and other advanced diagnostic technology across the network","Combined optical and audiology services at many locations for convenience","Staff continuity ensures patients see familiar faces year after year","Competitive pricing that balances quality with accessibility"],cons:["Relatively new group, so brand recognition is lower than established chains","Services and equipment may vary between practices as the network standardises","Frame selection depends on the individual practice and may be more limited than large chains"]},faqs:[{q:"What is Bayfields Opticians?",a:"Bayfields is a group of independent opticians and audiologists that has grown by acquiring established independent practices across England and Wales. Founded in 2015, the group preserves the local character, staff, and patient relationships of each practice while investing in advanced clinical technology and adding audiology services. The result is a network of practices that feel like your trusted local optician but benefit from the resources of a larger group."},{q:"Will my local practice change now that it has joined Bayfields?",a:"Bayfields' acquisition model is specifically designed to minimise disruption. The staff you know will typically remain, and the practice continues to operate in the same location with the same commitment to personal care. What changes behind the scenes includes investment in new equipment such as OCT scanners, improved staff training programmes, and group purchasing power that can lead to better value for patients. Many patients notice an improvement in available technology without any loss of the personal touch."},{q:"Does Bayfields offer hearing tests?",a:"Yes, many Bayfields practices now offer hearing assessments alongside their optical services. This is part of Bayfields' strategy to create combined opticians-and-audiologists practices. Hearing tests are free, and if hearing loss is identified, a range of private hearing aids is available from leading manufacturers. The availability of audiology services varies by practice, so check when booking."},{q:"Where are Bayfields practices located?",a:"Bayfields operates approximately 60 practices across England and Wales. Locations span southern England, the Midlands, East Anglia, and parts of Wales. The group continues to grow by acquiring additional independent practices. You can search for your nearest Bayfields practice by entering your postcode on eyetest.co.uk."},{q:"Is Bayfields an independent opticians?",a:"Bayfields describes itself as a group of independent practices. While the individual practices are now part of the Bayfields group rather than being independently owned, the group's philosophy is to preserve the independent character of each practice. Staff, clinical approaches, and patient relationships are maintained, and each practice retains its community focus. Bayfields is not part of a large multinational corporation like some chain opticians."},{q:"How much does an eye test cost at Bayfields?",a:"NHS-funded eye tests are free for all eligible patients at Bayfields practices, just as at any other UK optician. Private eye tests start from around £30, and enhanced examinations with OCT scanning are available from approximately £40. Prices may vary slightly between practices. Contact lens assessments start from £35."},{q:"Does Bayfields offer OCT scanning?",a:"Yes, Bayfields has invested in OCT (Optical Coherence Tomography) technology across its network, and this scanning is available at most of its practices. OCT provides detailed 3D images of the retina and optic nerve head, enabling early detection of conditions such as glaucoma and macular degeneration. It is available as part of the enhanced eye examination for an additional fee."},{q:"Can I book a Bayfields appointment through eyetest.co.uk?",a:"Yes, Bayfields practices are available for booking through eyetest.co.uk. Simply enter your postcode to find your nearest practice, choose your appointment type, and select a convenient date and time. You will receive an email confirmation with all the details you need for your visit."}]},{slug:"duncan-and-todd",name:"Duncan & Todd Group",shortName:"Duncan & Todd",brandColor:"#00695c",description:"Duncan & Todd is a leading Scottish opticians group headquartered in Aberdeen, with practices across Scotland and the north of England. Originally established as a single practice, they have grown into one of Scotland's most respected optical groups through a combination of organic growth and acquisitions. They are known for their clinical expertise, wide range of premium eyewear, and strong ties to the communities they serve.",services:["NHS Eye Tests","Private Eye Tests","Contact Lenses","Glasses","Hearing Tests","Children's Eye Tests","OCT Scan"],storeCount:30,website:"https://www.duncanandtodd.com",priceRange:"Free NHS (Scotland) / From £25 private",nhsAvailable:!0,available:!0,highlights:["Scotland's leading independent opticians group","Free NHS eye tests available to all residents in Scotland","Premium eyewear selection including exclusive brands","Strong heritage and community involvement across northern UK"],founded:"1972",storeLocations:["edinburgh","glasgow","aberdeen","dundee","inverness","stirling","perth","newcastle","sunderland","durham","middlesbrough","darlington","carlisle","leeds","york"],history:"Duncan & Todd was founded in 1972 by Ian Todd, who opened his first optical practice in Aberdeen. The business was built on a foundation of clinical excellence and personal service, quickly establishing a reputation as one of the north-east of Scotland's most trusted opticians. Aberdeen's thriving economy, driven by the North Sea oil industry, provided a strong base of patients who valued quality eyewear and thorough eye care, and the practice flourished.\n\nThroughout the 1980s, 1990s, and 2000s, Duncan & Todd expanded across Scotland, opening new practices in Edinburgh, Glasgow, Dundee, Inverness, Stirling, and Perth. The group also grew through the acquisition of well-established local practices, a strategy that allowed it to enter new communities with an existing patient base and experienced staff. A key advantage for Duncan & Todd in Scotland is the Scottish NHS system, which provides free eye tests to all Scottish residents regardless of age or income — a policy that has been in place since 2006 and has increased the frequency of eye testing across the country.\n\nMore recently, Duncan & Todd has extended its reach south of the border into the north of England, acquiring practices in Newcastle, Sunderland, Durham, and other northern English towns. This expansion has made Duncan & Todd a truly cross-border optical group, and the company now operates around 30 practices. The group has invested in modern clinical technology across its network, including OCT scanning and digital retinal photography, while maintaining the personal, community-focused approach that defined its founding practice in Aberdeen over five decades ago. Duncan & Todd also operates several audiology clinics, offering hearing tests and hearing aids alongside its optical services.",detailedServices:[{name:"NHS Eye Test",description:"A comprehensive eye examination funded by the NHS. In Scotland, all residents are entitled to a free NHS eye test regardless of age or income. In England, standard NHS eligibility criteria apply. The test includes visual acuity assessment, refraction, eye pressure measurement, and a detailed examination of the health of the eyes.",price:"Free (all Scottish residents / eligible English patients)",duration:"20-25 minutes",nhsCovered:!0},{name:"Private Eye Test",description:"A full eye examination for patients in England who do not qualify for NHS-funded testing. The test covers all aspects of vision and eye health, including refraction, binocular vision, and a thorough internal and external examination of the eyes. Private eye tests at Duncan & Todd are competitively priced and include a detailed report of findings.",price:"From £25",duration:"25-30 minutes",nhsCovered:!1},{name:"Enhanced Eye Examination with OCT",description:"An advanced eye test that includes OCT (Optical Coherence Tomography) scanning, producing detailed 3D images of the retina and optic nerve. This technology enables early detection of conditions such as glaucoma, macular degeneration, and diabetic retinopathy — often years before symptoms appear. Duncan & Todd recommends this as a baseline scan for patients over 25.",price:"From £35",duration:"30-35 minutes",nhsCovered:!1},{name:"Contact Lens Fitting",description:"A specialist appointment for patients wanting to try or change contact lenses. The consultation includes corneal curvature measurements, tear film evaluation, and a trial fitting with the most suitable lens type. Duncan & Todd offers a wide range of contact lenses, including daily disposables, monthly lenses, toric lenses for astigmatism, and multifocal options.",price:"From £30",duration:"30-40 minutes",nhsCovered:!1},{name:"Hearing Assessment",description:"A comprehensive hearing test provided at selected Duncan & Todd practices with audiology clinics. The assessment includes an ear examination, pure tone audiometry, and speech discrimination testing. If hearing loss is identified, the audiologist will discuss hearing aid options from leading manufacturers.",price:"Free",duration:"30 minutes",nhsCovered:!1},{name:"Children's Eye Test",description:"A child-friendly eye examination using age-appropriate techniques. In Scotland, all children receive free NHS eye tests, and Duncan & Todd optometrists are experienced in making the experience relaxed and enjoyable for younger patients. The test checks for common childhood vision issues including amblyopia, squint, and refractive errors.",price:"Free (NHS funded)",duration:"20-30 minutes",nhsCovered:!0}],bookingProcess:["Find your nearest Duncan & Todd practice by entering your postcode on eyetest.co.uk","Review available services and appointment types — including free NHS eye tests for Scottish residents","Choose a convenient date and time from the available slots","Enter your personal details and any relevant medical information","Receive an email confirmation with your appointment details and practice directions","Attend your appointment — bring your current glasses or contact lenses and any NHS exemption evidence (England only)"],prosAndCons:{pros:["Scotland's leading independent optical group with over 50 years of heritage","All Scottish residents receive free NHS eye tests at Duncan & Todd","Premium eyewear selection including brands not widely available at chain opticians","Community-focused practices with strong local ties and experienced staff","Investment in modern clinical technology including OCT scanning"],cons:["Geographic coverage is limited to Scotland and the north of England","Not all practices have audiology services — availability varies by location","Fewer locations than national chains, meaning longer travel for some patients"]},faqs:[{q:"Are eye tests free at Duncan & Todd in Scotland?",a:"Yes, all residents of Scotland are entitled to a free NHS eye test, regardless of age, income, or medical history. This applies at all Duncan & Todd practices in Scotland. The Scottish Government has provided universal free eye tests since 2006 as part of its commitment to preventive healthcare. If you live in England and visit a Duncan & Todd practice south of the border, standard NHS eligibility criteria apply."},{q:"Where does Duncan & Todd have practices?",a:"Duncan & Todd operates approximately 30 practices across Scotland and the north of England. In Scotland, you will find practices in Edinburgh, Glasgow, Aberdeen, Dundee, Inverness, Stirling, and Perth. In England, the group has practices in Newcastle, Sunderland, Durham, Middlesbrough, Darlington, Carlisle, Leeds, and York. The group continues to expand, particularly in northern England."},{q:"Is Duncan & Todd an independent opticians?",a:"Yes, Duncan & Todd is an independent optical group. It is not part of a multinational corporation like Boots (EssilorLuxottica) or Specsavers. The company was founded in Aberdeen in 1972 and has grown through a combination of organic expansion and acquisition of local practices. Its independent status allows it to choose its own range of frames, invest in the technology it considers most important, and maintain a distinctive approach to patient care."},{q:"What frame brands does Duncan & Todd stock?",a:"Duncan & Todd carries a curated selection of premium, designer, and independent frame brands. The range typically includes names such as Tom Ford, Gucci, Saint Laurent, Lindberg, and Silhouette, alongside more widely available brands like Ray-Ban and Hugo Boss. Each practice may have a slightly different selection, and staff can help you find frames that suit your face shape, prescription, and budget."},{q:"Does Duncan & Todd offer hearing care?",a:"Yes, Duncan & Todd provides hearing assessments and hearing aid services at selected practices. Hearing tests are free, and if hearing loss is identified, the audiologist will discuss a range of hearing aid options from leading manufacturers. Not all Duncan & Todd locations have audiology clinics, so check availability when booking."},{q:"Can I book a Duncan & Todd appointment through eyetest.co.uk?",a:"Yes, Duncan & Todd practices are available for booking through eyetest.co.uk. Enter your postcode to find your nearest practice, choose your appointment type, and select a date and time that suits you. You will receive a confirmation email with everything you need to know before your visit."},{q:"How does the NHS optical voucher scheme work in Scotland?",a:"In Scotland, all residents receive free NHS eye tests, and NHS optical vouchers are available to help with the cost of glasses. The voucher values are set by NHS Scotland and depend on your prescription and personal circumstances. Children, people on qualifying benefits, and those with complex prescriptions receive higher-value vouchers. Your Duncan & Todd dispensing optician will explain exactly how much the voucher covers and what, if anything, you will need to pay on top."},{q:"Does Duncan & Todd offer contact lenses?",a:"Yes, Duncan & Todd offers a full contact lens service including initial assessments, trial fittings, and ongoing supply. They stock a wide range of lenses from major manufacturers. Regular supply plans are available for daily and monthly wearers, and Duncan & Todd optometrists can fit specialist lenses including toric lenses for astigmatism and multifocal lenses for presbyopia."}]},{slug:"optical-express",name:"Optical Express",shortName:"Optical Express",brandColor:"#1565c0",description:"Optical Express is a major UK optical and laser eye surgery provider, offering both traditional optician services and specialist refractive surgery. With clinics across the UK and Ireland, they are one of the country's largest providers of laser eye surgery and lens replacement procedures, while also offering standard high-street optical services including eye tests, glasses, and contact lenses.",services:["NHS Eye Tests","Private Eye Tests","Contact Lenses","Glasses","Children's Eye Tests","OCT Scan"],storeCount:100,website:"https://www.opticalexpress.co.uk",priceRange:"Free NHS / From £25 private",nhsAvailable:!0,available:!1,highlights:["One of the UK's largest providers of laser eye surgery","Combines high-street optician services with specialist surgical clinics","Advanced diagnostic technology across all clinics","Nationwide network of clinics in major cities and towns"],founded:"1991",storeLocations:["london","croydon","bromley","kingston-upon-thames","brighton","reading","oxford","guildford","southampton","portsmouth","milton-keynes","crawley","basingstoke","bristol","bath","exeter","plymouth","bournemouth","swindon","cambridge","norwich","chelmsford","luton","peterborough","birmingham","coventry","wolverhampton","nottingham","leicester","derby","northampton","manchester","liverpool","chester","preston","leeds","sheffield","york","bradford","newcastle","sunderland","middlesbrough","cardiff","swansea","edinburgh","glasgow","aberdeen","dundee","belfast"],history:"Optical Express was founded in 1991 in Glasgow, Scotland, initially as a traditional high-street opticians chain. The company grew quickly during the 1990s, opening stores across Scotland and then expanding into England, Wales, and Northern Ireland. What distinguished Optical Express from many competitors was its early recognition of the commercial potential of laser eye surgery, which was emerging as a viable alternative to glasses and contact lenses during the same period. By the mid-1990s, Optical Express had begun investing in laser and refractive surgery services, positioning itself as both a conventional optician and a specialist surgical provider.\n\nThe laser eye surgery division of the business grew rapidly through the 2000s, and Optical Express became one of the UK's largest providers of LASIK, LASEK, and other refractive procedures. The company invested heavily in the latest laser technology and recruited experienced ophthalmic surgeons, building a network of dedicated surgical clinics alongside its standard opticians stores. This dual model — combining everyday optical services with specialist surgery — was unusual in the UK market and gave Optical Express a distinctive niche. The company also expanded into lens replacement surgery, offering implantable contact lenses and refractive lens exchange for patients who were not suitable candidates for laser treatment.\n\nToday, Optical Express operates approximately 100 clinics and stores across the United Kingdom and Ireland. The business is privately owned by its founder, David Moulsdale, and employs around 2,000 people. While the laser eye surgery division generates significant revenue and attention, Optical Express continues to operate standard optician services — including NHS eye tests, glasses dispensing, and contact lens fitting — at many of its locations. The company's clinics are typically located in city centres and major towns, and it has invested in advanced diagnostic equipment including OCT scanning, corneal topography, and wavefront aberrometry across its network.",detailedServices:[{name:"NHS Eye Test",description:"A standard NHS-funded eye examination for eligible patients. Optical Express optometrists carry out a full assessment of visual acuity, refraction, and eye health using modern diagnostic equipment. In Scotland, all residents receive free NHS eye tests. In England, Wales, and Northern Ireland, standard NHS eligibility criteria apply.",price:"Free (if eligible)",duration:"20-25 minutes",nhsCovered:!0},{name:"Private Eye Test",description:"A comprehensive eye examination for patients not eligible for NHS funding. The test includes detailed refraction, binocular vision assessment, and a thorough examination of the internal and external health of the eyes. Optical Express uses advanced clinical equipment and digital imaging across its clinics.",price:"From £25",duration:"25 minutes",nhsCovered:!1},{name:"Advanced Eye Examination with OCT",description:"An enhanced eye examination that includes OCT (Optical Coherence Tomography) scanning and digital retinal photography. This combination of technologies provides a comprehensive picture of the health of the retina, optic nerve, and macular area, enabling early detection of conditions such as glaucoma, macular degeneration, and diabetic retinopathy.",price:"From £40",duration:"30-35 minutes",nhsCovered:!1},{name:"Laser Eye Surgery Consultation",description:"A comprehensive initial consultation for patients considering laser eye surgery. The appointment includes a detailed eye examination, corneal topography mapping, wavefront aberrometry, pupil size measurement, and a tear film assessment. An ophthalmic surgeon will review the results and discuss whether you are a suitable candidate for LASIK, LASEK, or another refractive procedure.",price:"Free (no obligation)",duration:"60-90 minutes",nhsCovered:!1},{name:"Contact Lens Fitting",description:"A specialist consultation for patients wanting to start wearing contact lenses or explore different options. Includes corneal topography, tear film analysis, and a trial fitting with appropriate lenses. Optical Express offers a range of lens types from leading manufacturers, and monthly supply plans are available.",price:"From £30",duration:"30-40 minutes",nhsCovered:!1},{name:"Children's Eye Test",description:"An age-appropriate eye examination for children, checking for common childhood vision issues including lazy eye, squint, and refractive errors. All children under 16 qualify for a free NHS-funded eye test. Optical Express offers a selection of children's frames suitable for younger patients.",price:"Free (NHS funded)",duration:"20-25 minutes",nhsCovered:!0}],bookingProcess:["Search for your nearest Optical Express clinic by entering your postcode on eyetest.co.uk","Compare available services — from standard eye tests to laser eye surgery consultations","Select your preferred appointment type and choose a date and time","Enter your personal details and any relevant medical or prescription information","Receive a confirmation email with your appointment details, clinic location, and what to expect","Attend your appointment — for laser surgery consultations, allow up to 90 minutes for the comprehensive assessment"],prosAndCons:{pros:["One of the UK's largest and most experienced providers of laser eye surgery","Combines standard optician services with specialist surgical clinics under one brand","Advanced diagnostic technology including OCT, corneal topography, and wavefront aberrometry","Free, no-obligation laser eye surgery consultations to assess your suitability","Nationwide presence in major UK cities with modern, well-equipped clinics"],cons:["Not currently available for booking through eyetest.co.uk","The brand's strong association with laser surgery can overshadow its standard optician services","No hearing care services offered"]},faqs:[{q:"Is Optical Express only for laser eye surgery?",a:"No, Optical Express offers a full range of standard optician services alongside its laser eye surgery business. You can get NHS and private eye tests, buy glasses and sunglasses, and have contact lenses fitted at many of their locations. However, their reputation and marketing are heavily focused on refractive surgery, so many people are unaware that they also function as a conventional high-street optician."},{q:"How much does laser eye surgery cost at Optical Express?",a:"Laser eye surgery prices at Optical Express vary depending on the type of procedure and the complexity of your prescription. Prices typically start from around £595 per eye for standard LASEK and from £1,195 per eye for bladeless LASIK. More advanced procedures using wavefront-guided technology cost more. Optical Express offers free initial consultations and interest-free finance options to help spread the cost."},{q:"Is laser eye surgery safe?",a:"Laser eye surgery is one of the most commonly performed elective procedures in the world and has a high safety record. The vast majority of patients achieve excellent results, with many reaching 20/20 vision or better. However, like any surgical procedure, there are risks, including dry eyes, halos around lights, and, rarely, undercorrection or overcorrection. Optical Express will carry out a thorough assessment to determine whether you are a suitable candidate and will explain all potential risks before you decide to proceed."},{q:"Can I get a free eye test at Optical Express?",a:"Yes, Optical Express provides free NHS-funded eye tests for all eligible patients. In Scotland, all residents qualify for free NHS eye tests regardless of age or income. In England, Wales, and Northern Ireland, eligibility includes children under 16, adults over 60, those on qualifying benefits, and people with specific medical conditions. Laser eye surgery consultations are also free and carry no obligation."},{q:"Where are Optical Express clinics located?",a:"Optical Express operates approximately 100 clinics across the United Kingdom and Ireland, located in major cities and towns including London, Birmingham, Manchester, Leeds, Edinburgh, Glasgow, Aberdeen, Cardiff, Belfast, and many more. Their clinics are typically in city centre locations for easy access."},{q:"Can I book an Optical Express appointment through eyetest.co.uk?",a:"Optical Express is not currently available for direct booking through eyetest.co.uk. We list Optical Express on our platform so that customers can compare their services and prices with other opticians. To book an eye test or laser surgery consultation, visit opticalexpress.co.uk or call their booking line directly. We hope to offer Optical Express booking through our platform in the future."},{q:"Does Optical Express offer finance for laser eye surgery?",a:"Yes, Optical Express offers a range of finance options for laser eye surgery, including interest-free credit for qualifying patients. Monthly payment plans allow you to spread the cost of treatment over 12 to 60 months. Finance is subject to credit approval, and full details are discussed during the initial consultation."},{q:"What is the difference between LASIK and LASEK at Optical Express?",a:"LASIK and LASEK are both types of laser eye surgery, but they differ in how the laser accesses the cornea. LASIK involves creating a thin flap in the corneal surface before reshaping the underlying tissue with a laser — recovery is typically faster, with most patients seeing well within 24 hours. LASEK does not involve a flap; instead, the surface layer of the cornea is gently moved aside, and the laser reshapes the surface directly. LASEK recovery takes a few days longer, but it may be more suitable for patients with thinner corneas. Your Optical Express surgeon will recommend the best option based on your individual assessment."}]},{slug:"mands-opticians",name:"M&S Opticians",shortName:"M&S",brandColor:"#00573f",description:"M&S Opticians is the optical arm of Marks & Spencer, one of Britain's most trusted and iconic retail brands. Launched in 2017, M&S Opticians operates inside selected M&S stores across the UK in partnership with an experienced optical services provider. They offer a full range of eye care services including NHS and private eye tests, OCT scanning, contact lens fittings, and a carefully curated selection of quality eyewear. With the backing of the M&S name, customers can expect attentive service, stylish frames at fair prices, and the convenience of booking an eye test while visiting a store they already know and love.",services:["NHS Eye Tests","Private Eye Tests","Contact Lenses","Glasses","Children's Eye Tests","OCT Scan"],storeCount:37,website:"https://mandsopticians.com",priceRange:"Free NHS / From £20 private",nhsAvailable:!0,available:!0,highlights:["Backed by the trusted Marks & Spencer brand, known for quality and customer care","Conveniently located inside M&S stores — combine your eye test with everyday shopping","Quality frames at fair prices with a curated selection of stylish eyewear","NHS eye tests available for all eligible patients at every location"],founded:"2017",storeLocations:["birmingham","bournemouth","brighton","canterbury","cardiff","chester","derby","ealing","exeter","glasgow","harrogate","kingston-upon-thames","leeds","london","luton","manchester","milton-keynes","newcastle","norwich","oxford","plymouth","sheffield","southampton","st-albans","stoke-on-trent","swansea","torquay","warrington","woking","york"],history:"Marks & Spencer entered the optical market in 2017, launching M&S Opticians as a natural extension of the retailer's long-standing commitment to health, wellbeing, and quality. The move reflected a broader trend among major UK retailers to offer in-store health services, and M&S was well positioned to capitalise on the trust and loyalty its brand commands across the country. By placing opticians inside existing M&S stores, the company gave customers a convenient new reason to visit — combining an eye test with their regular shopping trip.\n\nRather than building an optical business from scratch, M&S chose a partnership model, working with experienced optical services providers to staff and operate the in-store practices. This approach ensured that customers received clinical care from fully qualified optometrists and dispensing opticians from day one, while benefiting from the familiar M&S environment and service standards. The partnership model also allowed M&S to scale the offering without the complexity of recruiting and managing its own clinical workforce, a pragmatic strategy that has served the brand well as it expanded from its initial pilot stores.\n\nToday, M&S Opticians operates in 37 locations across England, Scotland, and Wales, housed within some of Marks & Spencer's larger stores. The practices offer a full range of services including NHS-funded and private eye tests, enhanced OCT scanning, contact lens fittings, and children's eye tests. The frame collection is curated to reflect the M&S aesthetic — classic, well-made, and fairly priced — sitting alongside NHS-voucher options. While the network is still smaller than the major optical chains, M&S Opticians has carved out a loyal customer base drawn by the trusted brand name, quality frames, and the simple convenience of a high-street location they already visit regularly.",detailedServices:[{name:"NHS Eye Test",description:"A comprehensive eye examination carried out by a qualified optometrist, available free of charge to all eligible patients. Eligibility includes children under 16, adults over 60, those receiving qualifying benefits, and patients with certain medical conditions. The test covers visual acuity, refraction, eye pressure measurement, and an examination of the internal and external structures of the eye.",price:"Free (if eligible)",duration:"20-25 minutes",nhsCovered:!0},{name:"Private Eye Test",description:"A full eye examination for patients who do not qualify for NHS funding. The test includes all the same clinical checks as the NHS eye test — visual acuity, refraction, slit lamp examination, and ophthalmoscopy — providing a thorough assessment of your vision and eye health.",price:"From £20",duration:"25-30 minutes",nhsCovered:!1},{name:"Enhanced OCT Eye Test",description:"An advanced eye examination that includes Optical Coherence Tomography (OCT), a non-invasive scan that produces detailed cross-sectional images of the retina. OCT scanning can detect early signs of conditions such as glaucoma, macular degeneration, and diabetic retinopathy, often before symptoms appear. Recommended for patients who want the most thorough eye health assessment available.",price:"From £45",duration:"30-35 minutes",nhsCovered:!1},{name:"Contact Lens Fitting",description:"An initial assessment and fitting for contact lenses, carried out by a qualified optician. Includes measurements of corneal curvature, tear film evaluation, and a trial fitting with your chosen lens type. Your optician will advise on daily disposables, monthly lenses, or specialist lenses depending on your prescription and lifestyle.",price:"From £35",duration:"30-40 minutes",nhsCovered:!1},{name:"Children's Eye Test",description:"A specially adapted eye test designed for children, using age-appropriate charts and techniques. All children under 16 are entitled to a free NHS-funded eye test. The optometrist will check for common childhood vision problems including lazy eye, squint, and refractive errors. M&S stocks a range of children's frames, many available under the NHS voucher scheme.",price:"Free (NHS funded)",duration:"20-25 minutes",nhsCovered:!0},{name:"Style Consultation",description:"A complimentary one-to-one session with a dispensing optician to help you choose frames that suit your face shape, colouring, and personal style. The consultation covers frame materials, lens options, and coatings, helping you find eyewear that looks great and meets your practical needs. No purchase obligation.",price:"Free",duration:"15-20 minutes",nhsCovered:!1}],bookingProcess:["Search for your nearest M&S Opticians by entering your postcode on eyetest.co.uk","Compare available appointment slots and services at nearby M&S stores","Select your preferred date and time for your eye test","Enter your personal details and any relevant medical information","Receive confirmation of your appointment by email","Attend your appointment at the M&S Opticians practice inside your chosen M&S store"],prosAndCons:{pros:["Backed by one of the UK's most trusted household brands with a reputation for quality","Conveniently located inside M&S stores — easy to combine with regular shopping","Quality frames at fair prices with a curated, stylish selection","NHS eye tests available for all eligible patients"],cons:["Limited to just 37 locations across the UK, so not available in every town","No hearing care services offered alongside optical","A relatively new entrant to the optical market with a shorter track record than established chains"]},faqs:[{q:"Where are M&S Opticians located?",a:"M&S Opticians operates from 37 locations across England, Scotland, and Wales, all situated inside Marks & Spencer stores. You will find them in major cities and towns including London, Birmingham, Manchester, Leeds, Glasgow, Cardiff, Sheffield, and Newcastle, as well as smaller centres such as Harrogate, Canterbury, and St Albans. Each practice is located within the M&S store itself, making it easy to combine an eye test with your regular shopping trip."},{q:"Do M&S Opticians offer NHS eye tests?",a:"Yes, M&S Opticians provides free NHS-funded eye tests for all eligible patients. Eligibility includes children under 16, adults aged 60 and over, people receiving certain means-tested benefits, and individuals with specific medical conditions such as diabetes or glaucoma. In Scotland, all residents are entitled to a free NHS eye test regardless of age or income. If you are unsure whether you qualify, the team at your local M&S Opticians can advise you when you arrive."},{q:"Are M&S Opticians glasses expensive?",a:"M&S Opticians offers a range of frames at various price points, reflecting the Marks & Spencer approach of quality at fair prices. You will find options starting from budget-friendly NHS-voucher frames through to premium designer styles. The emphasis is on well-made, stylish eyewear that represents good value rather than being the cheapest or most expensive on the market. Lens packages including anti-reflection coatings and thinning options are available at competitive prices, and the team can help you find the best combination for your budget."},{q:"Can I book an M&S Opticians appointment online?",a:"Yes, you can search for available appointments at your nearest M&S Opticians through eyetest.co.uk. Simply enter your postcode, compare available dates and times at nearby M&S stores, and book directly. You will receive confirmation of your appointment by email. Booking online through eyetest.co.uk lets you compare availability across multiple M&S locations at a glance, making it easy to find a slot that fits your schedule."},{q:"What brands of glasses does M&S Opticians stock?",a:"M&S Opticians offers a curated selection of quality frames chosen to reflect the classic, well-made aesthetic that Marks & Spencer is known for. The range includes own-brand M&S frames alongside a selection of recognisable designer labels. While the selection may not be as vast as the largest optical chains, the emphasis is on quality, style, and value. The dispensing team can help you find frames that suit your face shape, lifestyle, and budget during a complimentary style consultation."},{q:"Is M&S Opticians an independent optician?",a:"M&S Opticians is not a fully independent optician — it operates as a partnership within Marks & Spencer stores. The optical practices are staffed and managed by an experienced optical services provider in collaboration with M&S, combining professional clinical care with the trusted M&S retail environment. This partnership model means you receive your eye care from fully qualified, registered optometrists and dispensing opticians while enjoying the comfort and familiarity of a Marks & Spencer store."}]},{slug:"ace-and-tate",name:"Ace & Tate",shortName:"Ace & Tate",brandColor:"#1a1a1a",description:"Ace & Tate is a Dutch eyewear brand founded in Amsterdam in 2013, known for making designer-quality glasses accessible and affordable. By cutting out traditional middlemen and designing frames in-house, they offer stylish prescription glasses with lenses included from around £98. With 17 stores across the UK — including 10 in London — Ace & Tate has become a go-to destination for fashion-conscious customers who want distinctive eyewear without the luxury price tag. Their stores are designed as welcoming, gallery-like spaces where trying on frames feels like a curated experience.",services:["Private Eye Tests","Contact Lenses","Glasses","Style Consultation"],storeCount:17,website:"https://www.aceandtate.com/gb",priceRange:"From £98 (frames + lenses)",nhsAvailable:!1,available:!0,highlights:["Affordable designer-quality frames designed in-house in Amsterdam","Trendy, gallery-inspired store experiences in prime city locations","Transparent all-in pricing — frames with prescription lenses from £98","Commitment to sustainability with recycled acetate and B-Corp certification"],founded:"2013",storeLocations:["brighton","bristol","cardiff","glasgow","leeds","london","manchester","oxford"],history:"Ace & Tate was founded in Amsterdam in 2013 by Mark de Lange, who set out to disrupt the traditional optical industry by offering high-quality, design-led eyewear at a fraction of the price charged by established luxury brands. The premise was simple but powerful: by designing frames in-house, manufacturing directly with trusted factories, and selling through their own stores and website, Ace & Tate could cut out the layers of middlemen that inflate eyewear prices across the industry. The brand quickly gained a following in the Netherlands and Belgium, attracting customers who wanted stylish, well-made glasses without paying hundreds of pounds for a designer label.\n\nAce & Tate expanded rapidly across Europe throughout the mid-2010s, entering the UK market with its first London stores. The brand became known not just for its products but for its retail experience — stores are designed as bright, minimalist spaces with a gallery-like aesthetic, often located in trendy neighbourhoods alongside independent boutiques and cafés. This positioning, combined with strong social media marketing and collaborations with artists and designers, helped Ace & Tate build a distinctive identity that resonated with a younger, design-aware audience. The brand also invested in an online try-at-home service, allowing customers to order frames to try before committing.\n\nToday, Ace & Tate operates 17 stores across the UK, with 10 in London and additional locations in Brighton, Bristol, Cardiff, Glasgow, Leeds, Manchester, and Oxford. The brand positions itself as the accessible alternative to luxury eyewear — offering frames with prescription lenses from around £98, with no hidden costs for standard single-vision lenses. Ace & Tate has also made sustainability a core part of its identity, using recycled acetate and bio-based materials, and achieving B-Corp certification. While they do not offer NHS-funded eye tests, their private eye test service and all-in pricing model make them a compelling choice for customers who value design, transparency, and ethical production.",detailedServices:[{name:"Eye Test",description:"A private eye examination carried out by a qualified optometrist at an Ace & Tate store. The test includes a thorough assessment of your vision and eye health, covering visual acuity, refraction, eye pressure, and an examination of the front and back of the eye. Results are used to provide an up-to-date prescription for glasses or contact lenses.",price:"From £25",duration:"20-25 minutes",nhsCovered:!1},{name:"Comprehensive Eye Test",description:"A more in-depth eye examination that includes additional diagnostic checks beyond the standard test. This may include digital retinal imaging, extended health screening, and a more detailed discussion of your visual needs. Recommended for patients who want a thorough assessment or who have a family history of eye conditions.",price:"From £50",duration:"30-35 minutes",nhsCovered:!1},{name:"Contact Lens Fitting",description:"An assessment and fitting for contact lenses, including corneal measurements, tear film evaluation, and a trial with your recommended lens type. Your optician will discuss options including daily disposables and monthly lenses, and advise on insertion, removal, and care. A follow-up appointment is included to check fit and comfort.",price:"From £50",duration:"30-40 minutes",nhsCovered:!1},{name:"Frame Styling Session",description:"A complimentary one-to-one session with an Ace & Tate stylist to help you find frames that suit your face shape, skin tone, and personal style. The team will guide you through the collection, explain frame materials and lens options, and help you narrow down your choices. No appointment needed — just walk in.",price:"Free",duration:"15-20 minutes",nhsCovered:!1},{name:"Glasses Adjustment",description:"A complimentary service to adjust and tighten your Ace & Tate glasses for a perfect fit. Whether your frames have become loose, uneven, or uncomfortable, the in-store team can make adjustments on the spot. This service is available for all Ace & Tate frames and is free of charge, no appointment required.",price:"Free",duration:"10 minutes",nhsCovered:!1}],bookingProcess:["Search for your nearest Ace & Tate store by entering your postcode on eyetest.co.uk","Find the nearest Ace & Tate location and check available services","Select the type of appointment you need — eye test, comprehensive test, or contact lens fitting","Choose your preferred date and time from the available slots","Enter your personal details to confirm your booking","Attend your appointment at the Ace & Tate store and browse frames before or after your test"],prosAndCons:{pros:["Transparent all-in pricing with frames and prescription lenses from £98 — no hidden extras","Design-led, stylish frames created by an in-house team in Amsterdam","Sustainable materials including recycled acetate, with B-Corp certification","Trendy, welcoming stores with a gallery-like atmosphere and helpful stylists"],cons:["Very limited UK coverage with only 17 stores, mostly concentrated in London","No NHS-funded eye tests — all services are private","No hearing care or clinical specialist services beyond standard eye care"]},faqs:[{q:"How much are Ace & Tate glasses?",a:"Ace & Tate offers prescription glasses starting from £98, which includes the frame and standard single-vision lenses — there are no hidden costs for basic prescriptions. Prices increase for more complex prescriptions, progressive (varifocal) lenses, and premium lens coatings such as blue-light filtering or extra-thin options. Sunglasses with prescription lenses start from a similar price point. The transparent pricing model means you know exactly what you are paying before you commit, with no surprise add-ons at the till."},{q:"Where are Ace & Tate stores in the UK?",a:"Ace & Tate operates 17 stores across the UK. Ten of these are in London, spread across popular neighbourhoods including Soho, Shoreditch, Covent Garden, Notting Hill, and King's Cross. Outside London, you will find stores in Brighton, Bristol, Cardiff, Glasgow, Leeds, Manchester, and Oxford. The stores are typically located in trendy, walkable areas alongside independent shops and cafés. If there is no store near you, Ace & Tate also offers a home try-on service where you can order up to four frames to try at home for free."},{q:"Do Ace & Tate offer NHS eye tests?",a:"No, Ace & Tate does not offer NHS-funded eye tests. All eye tests at Ace & Tate are private, starting from £25 for a standard examination and from £50 for a comprehensive test. They do not participate in the NHS optical voucher scheme for glasses either. If you are looking for a free NHS eye test, you would need to visit an optician that participates in the NHS scheme, such as Boots Opticians or Specsavers. You can use eyetest.co.uk to compare NHS and private options near you."},{q:"Are Ace & Tate frames good quality?",a:"Ace & Tate frames are designed in-house at their Amsterdam studio and manufactured using high-quality materials including Italian Mazzucchelli acetate, lightweight stainless steel, and increasingly, recycled and bio-based acetate. The brand puts significant emphasis on design and build quality, with frames that feel solid and well-finished. Hinges, nose pads, and temple tips are designed for comfort and durability. As a certified B-Corp, Ace & Tate also meets verified standards for social and environmental performance, which extends to their material sourcing and production processes."},{q:"Can I book an Ace & Tate eye test online?",a:"Yes, you can book an eye test at your nearest Ace & Tate store through eyetest.co.uk. Simply enter your postcode, find the nearest location, and select an available appointment slot. You can also book directly through the Ace & Tate website or by contacting the store. Booking through eyetest.co.uk lets you compare availability and prices across multiple opticians in your area, making it easy to find the best option for your needs and schedule."},{q:"What makes Ace & Tate different from other opticians?",a:"Ace & Tate operates on a direct-to-consumer model that cuts out the traditional middlemen in the eyewear industry — the brand designs its own frames, works directly with manufacturers, and sells through its own stores and website. This means they can offer designer-quality glasses at a significantly lower price than traditional opticians selling third-party designer labels. Their transparent pricing — frames with lenses from £98 — their design-first approach, sustainability commitments, and curated retail experience set them apart from both high-street chains and luxury boutiques."}]}];a.s(["getAllSlugs",0,function(){return b.map(a=>a.slug)},"getAvailableOpticians",0,function(){return b.filter(a=>a.available)},"getOpticianBySlug",0,function(a){return b.find(b=>b.slug===a)},"getOpticiansByLocation",0,function(a){return b.filter(b=>b.storeLocations.includes(a))},"getUnavailableOpticians",0,function(){return b.filter(a=>!a.available)},"opticians",0,b])}];

//# sourceMappingURL=Documents_Claude_Projects_eyetest_co_uk_src_data_opticians_ts_20mwx56._.js.map